static void jbig2_set_bits ( byte * line , int x0 , int x1 ) {
 int a0 , a1 , b0 , b1 , a ;
 a0 = x0 >> 3 ;
 a1 = x1 >> 3 ;
 b0 = x0 & 7 ;
 b1 = x1 & 7 ;
 if ( a0 == a1 ) {
 line [ a0 ] |= lm [ b0 ] & rm [ b1 ] ;
 }
 else {
 line [ a0 ] |= lm [ b0 ] ;
 for ( a = a0 + 1 ;
 a < a1 ;
 a ++ ) line [ a ] = 0xFF ;
 if ( b1 ) line [ a1 ] |= rm [ b1 ] ;
 }
 }

static int jbig2_find_changing_element ( const byte * line , int x , int w ) {
 int a , b ;
 if ( line == 0 ) return w ;
 if ( x == - 1 ) {
 a = 0 ;
 x = 0 ;
 }
 else {
 a = getbit ( line , x ) ;
 x ++ ;
 }
 while ( x < w ) {
 b = getbit ( line , x ) ;
 if ( a != b ) break ;
 x ++ ;
 }
 return x ;
 }

static int jbig2_find_changing_element_of_color ( const byte * line , int x , int w , int color ) {
 if ( line == 0 ) return w ;
 x = jbig2_find_changing_element ( line , x , w ) ;
 if ( x < w && getbit ( line , x ) != color ) x = jbig2_find_changing_element ( line , x , w ) ;
