int decodenetnum ( const char * num , sockaddr_u * netnum ) {
 struct addrinfo hints , * ai = NULL ;
 int err ;
 u_short port ;
 const char * cp ;
 const char * port_str ;
 char * pp ;
 char * np ;
 char name [ 80 ] ;
 REQUIRE ( num != NULL ) ;
 REQUIRE ( strlen ( num ) < sizeof ( name ) ) ;
 port_str = NULL ;
 if ( '[' != num [ 0 ] ) {
 pp = strchr ( num , ':' ) ;
 if ( NULL == pp ) cp = num ;
 else if ( NULL != strchr ( pp + 1 , ':' ) ) cp = num ;
 else {
 strlcpy ( name , num , sizeof ( name ) ) ;
 cp = name ;
 pp = strchr ( cp , ':' ) ;
 * pp = '\0' ;
 port_str = pp + 1 ;
 }
 }
 else {
 cp = num + 1 ;
 np = name ;
 while ( * cp && ']' != * cp ) * np ++ = * cp ++ ;
 * np = 0 ;
 if ( ']' == cp [ 0 ] && ':' == cp [ 1 ] && '\0' != cp [ 2 ] ) port_str = & cp [ 2 ] ;
 cp = name ;
 }
 ZERO ( hints ) ;
 hints . ai_flags = Z_AI_NUMERICHOST ;
 err = getaddrinfo ( cp , "ntp" , & hints , & ai ) ;
 if ( err != 0 ) return 0 ;
 INSIST ( ai -> ai_addrlen <= sizeof ( * netnum ) ) ;
 ZERO ( * netnum ) ;
 memcpy ( netnum , ai -> ai_addr , ai -> ai_addrlen ) ;
 freeaddrinfo ( ai ) ;
 if ( NULL == port_str || 1 != sscanf ( port_str , "%hu" , & port ) ) port = NTP_PORT ;
 SET_PORT ( netnum , port ) ;
 return 1 ;
 }

void jpc_qmfb_split_col ( jpc_fix_t * a , int numrows , int stride , int parity ) {
 int bufsize = JPC_CEILDIVPOW2 ( numrows , 1 ) ;
 jpc_fix_t splitbuf [ QMFB_SPLITBUFSIZE ] ;
 jpc_fix_t * buf = splitbuf ;
 register jpc_fix_t * srcptr ;
 register jpc_fix_t * dstptr ;
 register int n ;
 register int m ;
 int hstartcol ;
 if ( bufsize > QMFB_SPLITBUFSIZE ) {
 if ( ! ( buf = jas_alloc2 ( bufsize , sizeof ( jpc_fix_t ) ) ) ) {
 abort ( ) ;
 }
 }
 if ( numrows >= 2 ) {
 hstartcol = ( numrows + 1 - parity ) >> 1 ;
 m = numrows - hstartcol ;
 n = m ;
 dstptr = buf ;
 srcptr = & a [ ( 1 - parity ) * stride ] ;
 while ( n -- > 0 ) {
 * dstptr = * srcptr ;
 ++ dstptr ;
 srcptr += stride << 1 ;
 }
 dstptr = & a [ ( 1 - parity ) * stride ] ;
 srcptr = & a [ ( 2 - parity ) * stride ] ;
 n = numrows - m - ( ! parity ) ;
 while ( n -- > 0 ) {
 * dstptr = * srcptr ;
 dstptr += stride ;
 srcptr += stride << 1 ;
 }
 dstptr = & a [ hstartcol * stride ] ;
 srcptr = buf ;
 n = m ;
 while ( n -- > 0 ) {
 * dstptr = * srcptr ;
 dstptr += stride ;
 ++ srcptr ;
 }
 }
 if ( buf != splitbuf ) {
 jas_free ( buf ) ;
 }
 }

