static inline int rawv6_rcv_skb ( struct sock * sk , struct sk_buff * skb ) {
 if ( ( raw6_sk ( sk ) -> checksum || sk -> sk_filter ) && skb_checksum_complete ( skb ) ) {
 atomic_inc ( & sk -> sk_drops ) ;
 kfree_skb ( skb ) ;
 return NET_RX_DROP ;
 }
 if ( sock_queue_rcv_skb ( sk , skb ) < 0 ) {
 kfree_skb ( skb ) ;
 return NET_RX_DROP ;
 }
 return 0 ;
 }

int udpv6_queue_rcv_skb ( struct sock * sk , struct sk_buff * skb ) {
 struct udp_sock * up = udp_sk ( sk ) ;
 int rc ;
 int is_udplite = IS_UDPLITE ( sk ) ;
 if ( ! xfrm6_policy_check ( sk , XFRM_POLICY_IN , skb ) ) goto drop ;
 if ( ( is_udplite & UDPLITE_RECV_CC ) && UDP_SKB_CB ( skb ) -> partial_cov ) {
 if ( up -> pcrlen == 0 ) {
 LIMIT_NETDEBUG ( KERN_WARNING "UDPLITE6: partial coverage" " %d while full coverage %d requested\n" , UDP_SKB_CB ( skb ) -> cscov , skb -> len ) ;
 goto drop ;
 }
 if ( UDP_SKB_CB ( skb ) -> cscov < up -> pcrlen ) {
 LIMIT_NETDEBUG ( KERN_WARNING "UDPLITE6: coverage %d " "too small, need min %d\n" , UDP_SKB_CB ( skb ) -> cscov , up -> pcrlen ) ;
 goto drop ;
 }
 }
 if ( sk -> sk_filter ) {
 if ( udp_lib_checksum_complete ( skb ) ) goto drop ;
 }
 if ( ( rc = sock_queue_rcv_skb ( sk , skb ) ) < 0 ) {
 if ( rc == - ENOMEM ) UDP6_INC_STATS_BH ( sock_net ( sk ) , UDP_MIB_RCVBUFERRORS , is_udplite ) ;
 goto drop_no_sk_drops_inc ;
 }
 return 0 ;
 drop : atomic_inc ( & sk -> sk_drops ) ;
 drop_no_sk_drops_inc : UDP6_INC_STATS_BH ( sock_net ( sk ) , UDP_MIB_INERRORS , is_udplite ) ;
 kfree_skb ( skb ) ;
 return - 1 ;
 }

static jpc_enc_cblk_t * cblk_create ( jpc_enc_cblk_t * cblk , jpc_enc_cp_t * cp , jpc_enc_prc_t * prc ) {
 jpc_enc_band_t * band ;
 uint_fast32_t cblktlx ;
 uint_fast32_t cblktly ;
 uint_fast32_t cblkbrx ;
 uint_fast32_t cblkbry ;
 jpc_enc_rlvl_t * rlvl ;
 uint_fast32_t cblkxind ;
 uint_fast32_t cblkyind ;
 uint_fast32_t cblkno ;
 uint_fast32_t tlcblktlx ;
 uint_fast32_t tlcblktly ;
 cblkno = cblk - prc -> cblks ;
 cblkxind = cblkno % prc -> numhcblks ;
 cblkyind = cblkno / prc -> numhcblks ;
 rlvl = prc -> band -> rlvl ;
 cblk -> prc = prc ;
 cblk -> numpasses = 0 ;
 cblk -> passes = 0 ;
 cblk -> numencpasses = 0 ;
 cblk -> numimsbs = 0 ;
 cblk -> numlenbits = 0 ;
 cblk -> stream = 0 ;
 cblk -> mqenc = 0 ;
 cblk -> flags = 0 ;
 cblk -> numbps = 0 ;
 cblk -> curpass = 0 ;
 cblk -> data = 0 ;
 cblk -> savedcurpass = 0 ;
 cblk -> savednumlenbits = 0 ;
 cblk -> savednumencpasses = 0 ;
 band = prc -> band ;
 tlcblktlx = JPC_FLOORTOMULTPOW2 ( prc -> tlx , rlvl -> cblkwidthexpn ) ;
 tlcblktly = JPC_FLOORTOMULTPOW2 ( prc -> tly , rlvl -> cblkheightexpn ) ;
 cblktlx = JAS_MAX ( tlcblktlx + ( cblkxind << rlvl -> cblkwidthexpn ) , prc -> tlx ) ;
 cblktly = JAS_MAX ( tlcblktly + ( cblkyind << rlvl -> cblkheightexpn ) , prc -> tly ) ;
 cblkbrx = JAS_MIN ( tlcblktlx + ( ( cblkxind + 1 ) << rlvl -> cblkwidthexpn ) , prc -> brx ) ;
 cblkbry = JAS_MIN ( tlcblktly + ( ( cblkyind + 1 ) << rlvl -> cblkheightexpn ) , prc -> bry ) ;
 assert ( cblktlx < cblkbrx && cblktly < cblkbry ) ;
 if ( ! ( cblk -> data = jas_seq2d_create ( 0 , 0 , 0 , 0 ) ) ) {
 goto error ;
 }
 jas_seq2d_bindsub ( cblk -> data , band -> data , cblktlx , cblktly , cblkbrx , cblkbry ) ;
 return cblk ;
 error : cblk_destroy ( cblk ) ;
 return 0 ;
 }

