 b_lambda = s -> last_lambda_for [ AV_PICTURE_TYPE_B ] ;
 if ( ! b_lambda ) b_lambda = p_lambda ;
 lambda2 = ( b_lambda * b_lambda + ( 1 << FF_LAMBDA_SHIFT ) / 2 ) >> FF_LAMBDA_SHIFT ;
