 c -> height = s -> height >> scale ;
 c -> flags = CODEC_FLAG_QSCALE | CODEC_FLAG_PSNR | CODEC_FLAG_INPUT_PRESERVED ;
 c -> flags |= s -> avctx -> flags & CODEC_FLAG_QPEL ;
