 i < s -> max_b_frames + 2 ;
 i ++ ) {
 int ysize = c -> width * c -> height ;
 int csize = ( c -> width / 2 ) * ( c -> height / 2 ) ;
 Picture pre_input , * pre_input_ptr = i ? s -> input_picture [ i - 1 ] : s -> next_picture_ptr ;
