 s -> dstptr [ 1 ] = bufptr [ 1 ] ;
 s -> dstptr [ s -> frame . linesize [ 0 ] ] = bufptr [ s -> frame . linesize [ 0 ] ] ;
 s -> dstptr [ s -> frame . linesize [ 0 ] + 1 ] = bufptr [ s -> frame . linesize [ 0 ] + 1 ] ;
