 for ( x = 0 ;
 x < len ;
 x ++ , ptr += 4 ) * ( uint32_t * ) ptr = ( buf [ x ] << 16 ) + ( buf [ len + x ] << 8 ) + buf [ len + len + x ] ;
 }
 buf += maplength ;
 ptr = p -> data [ 0 ] ;
