 buf += 4 ;
 if ( colors < 0 || colors > 256 ) {
 av_log ( avctx , AV_LOG_ERROR , "Error color count - %i(0x%X)\n" , colors , colors ) ;
 return AVERROR_INVALIDDATA ;
 }
 if ( buf_end - buf < ( colors + 1 ) * 8 ) return AVERROR_INVALIDDATA ;
 pal = ( uint32_t * ) p -> data [ 1 ] ;
 for ( i = 0 ;
 i <= colors ;
 i ++ ) {
