 if ( buf_end - buf < code + 1 ) return AVERROR_INVALIDDATA ;
 memcpy ( out , buf , code + 1 ) ;
 out += code + 1 ;
 buf += code + 1 ;
 left -= 2 + code ;
 tsize += code + 1 ;
 }
