 if ( s -> nb_samples < 16 ) {
 for ( chan = 0 ;
 chan < avctx -> channels ;
 chan ++ ) {
 int32_t * decoded = s -> decoded [ chan ] ;
 for ( i = 0 ;
 i < s -> nb_samples ;
 i ++ ) decoded [ i ] = get_sbits ( gb , avctx -> bits_per_coded_sample ) ;
 }
