 i < chan ;
 i ++ ) {
 if ( s -> mcdparams [ i ] . present && s -> mcdparams [ i ] . index == 1 ) if ( ret = decode_channel ( s , s -> mcdparams [ i ] . chan2 ) ) return ret ;
 if ( ret = decode_channel ( s , s -> mcdparams [ i ] . chan1 ) ) return ret ;
