 if ( avpkt -> size < hdr_size * avctx -> channels ) {
 av_log ( avctx , AV_LOG_ERROR , "packet size is too small\n" ) ;
 return AVERROR ( EINVAL ) ;
 }
 if ( esc -> data [ 0 ] ) {
