 esc -> fib_acc [ 0 ] = avpkt -> data [ 1 ] + 128 ;
 if ( avctx -> channels == 2 ) esc -> fib_acc [ 1 ] = avpkt -> data [ 2 + chan_size + 1 ] + 128 ;
 }
