 int t ;
 r -> is16 = get_bits1 ( gb ) ;
 if ( r -> is16 ) {
 s -> current_picture_ptr -> f . mb_type [ mb_pos ] = MB_TYPE_INTRA16x16 ;
 r -> block_type = RV34_MB_TYPE_INTRA16x16 ;
 t = get_bits ( gb , 2 ) ;
 fill_rectangle ( intra_types , 4 , 4 , r -> intra_types_stride , t , sizeof ( intra_types [ 0 ] ) ) ;
