 if ( s -> umvplus ) mx = h263p_decode_umotion ( s , pred_x ) ;
 else mx = ff_h263_decode_motion ( s , pred_x , 1 ) ;
 if ( mx >= 0xffff ) return - 1 ;
 if ( s -> umvplus ) my = h263p_decode_umotion ( s , pred_y ) ;
 else my = ff_h263_decode_motion ( s , pred_y , 1 ) ;
