 mot_val0 [ 0 ] = mot_val0 [ 2 ] = mot_val0 [ 0 + 2 * stride ] = mot_val0 [ 2 + 2 * stride ] = mot_val0 [ 1 ] = mot_val0 [ 3 ] = mot_val0 [ 1 + 2 * stride ] = mot_val0 [ 3 + 2 * stride ] = mot_val1 [ 0 ] = mot_val1 [ 2 ] = mot_val1 [ 0 + 2 * stride ] = mot_val1 [ 2 + 2 * stride ] = mot_val1 [ 1 ] = mot_val1 [ 3 ] = mot_val1 [ 1 + 2 * stride ] = mot_val1 [ 3 + 2 * stride ] = 0 ;
