 int16_t * mot_val = ff_h263_pred_motion ( s , 0 , 0 , & mx , & my ) ;
 s -> mv_dir = MV_DIR_FORWARD ;
 mx = ff_h263_decode_motion ( s , mx , 1 ) ;
 my = ff_h263_decode_motion ( s , my , 1 ) ;
 s -> mv [ 0 ] [ 0 ] [ 0 ] = mx ;
 s -> mv [ 0 ] [ 0 ] [ 1 ] = my ;
