 s -> dsp . clear_blocks ( s -> block [ 0 ] ) ;
 dquant = cbpc & 4 ;
 s -> mb_intra = 1 ;
 intra : s -> current_picture . f . mb_type [ xy ] = MB_TYPE_INTRA ;
