static void process_tree ( struct rev_info * revs , struct tree * tree , show_object_fn show , struct name_path * path , struct strbuf * base , const char * name , void * cb_data ) {
 struct object * obj = & tree -> object ;
 struct tree_desc desc ;
 struct name_entry entry ;
 struct name_path me ;
 enum interesting match = revs -> diffopt . pathspec . nr == 0 ? all_entries_interesting : entry_not_interesting ;
 int baselen = base -> len ;
 if ( ! revs -> tree_objects ) return ;
 if ( ! obj ) die ( "bad tree object" ) ;
 if ( obj -> flags & ( UNINTERESTING | SEEN ) ) return ;
 if ( parse_tree_gently ( tree , revs -> ignore_missing_links ) < 0 ) {
 if ( revs -> ignore_missing_links ) return ;
 die ( "bad tree object %s" , oid_to_hex ( & obj -> oid ) ) ;
 }
 obj -> flags |= SEEN ;
 show ( obj , path , name , cb_data ) ;
 me . up = path ;
 me . elem = name ;
 me . elem_len = strlen ( name ) ;
 if ( ! match ) {
 strbuf_addstr ( base , name ) ;
 if ( base -> len ) strbuf_addch ( base , '/' ) ;
 }
 init_tree_desc ( & desc , tree -> buffer , tree -> size ) ;
 while ( tree_entry ( & desc , & entry ) ) {
 if ( match != all_entries_interesting ) {
 match = tree_entry_interesting ( & entry , base , 0 , & revs -> diffopt . pathspec ) ;
 if ( match == all_entries_not_interesting ) break ;
 if ( match == entry_not_interesting ) continue ;
 }
 if ( S_ISDIR ( entry . mode ) ) process_tree ( revs , lookup_tree ( entry . sha1 ) , show , & me , base , entry . path , cb_data ) ;
 else if ( S_ISGITLINK ( entry . mode ) ) process_gitlink ( revs , entry . sha1 , show , & me , entry . path , cb_data ) ;
 else process_blob ( revs , lookup_blob ( entry . sha1 ) , show , & me , entry . path , cb_data ) ;
 }
 strbuf_setlen ( base , baselen ) ;
 free_tree_buffer ( tree ) ;
 }

static void process_blob ( struct rev_info * revs , struct blob * blob , show_object_fn show , struct name_path * path , const char * name , void * cb_data ) {
 struct object * obj = & blob -> object ;
 if ( ! revs -> blob_objects ) return ;
 if ( ! obj ) die ( "bad blob object" ) ;
 if ( obj -> flags & ( UNINTERESTING | SEEN ) ) return ;
 obj -> flags |= SEEN ;
 show ( obj , path , name , cb_data ) ;
 }

void traverse_commit_list ( struct rev_info * revs , show_commit_fn show_commit , show_object_fn show_object , void * data ) {
 int i ;
 struct commit * commit ;
 struct strbuf base ;
 strbuf_init ( & base , PATH_MAX ) ;
 while ( ( commit = get_revision ( revs ) ) != NULL ) {
 if ( commit -> tree ) add_pending_tree ( revs , commit -> tree ) ;
 show_commit ( commit , data ) ;
 }
 for ( i = 0 ;
 i < revs -> pending . nr ;
 i ++ ) {
 struct object_array_entry * pending = revs -> pending . objects + i ;
 struct object * obj = pending -> item ;
 const char * name = pending -> name ;
 const char * path = pending -> path ;
 if ( obj -> flags & ( UNINTERESTING | SEEN ) ) continue ;
 if ( obj -> type == OBJ_TAG ) {
 obj -> flags |= SEEN ;
 show_object ( obj , NULL , name , data ) ;
 continue ;
 }
 if ( ! path ) path = "" ;
 if ( obj -> type == OBJ_TREE ) {
 process_tree ( revs , ( struct tree * ) obj , show_object , NULL , & base , path , data ) ;
 continue ;
 }
 if ( obj -> type == OBJ_BLOB ) {
 process_blob ( revs , ( struct blob * ) obj , show_object , NULL , path , data ) ;
 continue ;
 }
 die ( "unknown pending object %s (%s)" , oid_to_hex ( & obj -> oid ) , name ) ;
 }
 object_array_clear ( & revs -> pending ) ;
 strbuf_release ( & base ) ;
 }

static void finish_object ( struct object * obj , const struct name_path * path , const char * name , void * cb_data ) {
 struct rev_list_info * info = cb_data ;
 if ( obj -> type == OBJ_BLOB && ! has_object_file ( & obj -> oid ) ) die ( "missing blob object '%s'" , oid_to_hex ( & obj -> oid ) ) ;
