 uint8_t * dst ;
 dst = s -> vga . vram_ptr + ( offset &= s -> cirrus_addr_mask ) ;
 for ( x = 0 ;
 x < 8 ;
 x ++ ) {
 if ( val & 0x80 ) {
 * dst = s -> cirrus_shadow_gr1 ;
 * ( dst + 1 ) = s -> vga . gr [ 0x11 ] ;
 }
 else if ( mode == 5 ) {
 * dst = s -> cirrus_shadow_gr0 ;
 * ( dst + 1 ) = s -> vga . gr [ 0x10 ] ;
