 val <<= 1 ;
 dst += 2 ;
 }
 memory_region_set_dirty ( & s -> vga . vram , offset , 16 ) ;
 }

kadm5_ret_t kadm5_create_policy_internal ( void * server_handle , kadm5_policy_ent_t entry , long mask ) {
 kadm5_server_handle_t handle = server_handle ;
 osa_policy_ent_rec pent ;
 int ret ;
 char * p ;
 CHECK_HANDLE ( server_handle ) ;
 if ( ( entry == ( kadm5_policy_ent_t ) NULL ) || ( entry -> policy == NULL ) ) return EINVAL ;
 if ( strlen ( entry -> policy ) == 0 ) return KADM5_BAD_POLICY ;
 if ( ! ( mask & KADM5_POLICY ) ) return KADM5_BAD_MASK ;
 if ( ( mask & KADM5_POLICY_ALLOWED_KEYSALTS ) && entry -> allowed_keysalts != NULL ) {
 ret = validate_allowed_keysalts ( entry -> allowed_keysalts ) ;
 if ( ret ) return ret ;
 }
 memset ( & pent , 0 , sizeof ( pent ) ) ;
 pent . name = entry -> policy ;
 p = entry -> policy ;
 while ( * p != '\0' ) {
 if ( * p < ' ' || * p > '~' ) return KADM5_BAD_POLICY ;
 else p ++ ;
 }
 if ( ! ( mask & KADM5_PW_MAX_LIFE ) ) pent . pw_max_life = 0 ;
 else pent . pw_max_life = entry -> pw_max_life ;
 if ( ! ( mask & KADM5_PW_MIN_LIFE ) ) pent . pw_min_life = 0 ;
 else {
 if ( ( mask & KADM5_PW_MAX_LIFE ) ) {
 if ( entry -> pw_min_life > entry -> pw_max_life && entry -> pw_max_life != 0 ) return KADM5_BAD_MIN_PASS_LIFE ;
 }
 pent . pw_min_life = entry -> pw_min_life ;
 }
 if ( ! ( mask & KADM5_PW_MIN_LENGTH ) ) pent . pw_min_length = MIN_PW_LENGTH ;
 else {
 if ( entry -> pw_min_length < MIN_PW_LENGTH ) return KADM5_BAD_LENGTH ;
 pent . pw_min_length = entry -> pw_min_length ;
 }
 if ( ! ( mask & KADM5_PW_MIN_CLASSES ) ) pent . pw_min_classes = MIN_PW_CLASSES ;
 else {
 if ( entry -> pw_min_classes > MAX_PW_CLASSES || entry -> pw_min_classes < MIN_PW_CLASSES ) return KADM5_BAD_CLASS ;
 pent . pw_min_classes = entry -> pw_min_classes ;
 }
 if ( ! ( mask & KADM5_PW_HISTORY_NUM ) ) pent . pw_history_num = MIN_PW_HISTORY ;
 else {
 if ( entry -> pw_history_num < MIN_PW_HISTORY ) return KADM5_BAD_HISTORY ;
 else pent . pw_history_num = entry -> pw_history_num ;
 }
 if ( ! ( mask & KADM5_REF_COUNT ) ) pent . policy_refcnt = 0 ;
 else pent . policy_refcnt = entry -> policy_refcnt ;
 if ( handle -> api_version >= KADM5_API_VERSION_4 ) {
 if ( ! ( mask & KADM5_POLICY_ATTRIBUTES ) ) pent . attributes = 0 ;
 else pent . attributes = entry -> attributes ;
 if ( ! ( mask & KADM5_POLICY_MAX_LIFE ) ) pent . max_life = 0 ;
 else pent . max_life = entry -> max_life ;
 if ( ! ( mask & KADM5_POLICY_MAX_RLIFE ) ) pent . max_renewable_life = 0 ;
 else pent . max_renewable_life = entry -> max_renewable_life ;
 if ( ! ( mask & KADM5_POLICY_ALLOWED_KEYSALTS ) ) pent . allowed_keysalts = 0 ;
 else pent . allowed_keysalts = entry -> allowed_keysalts ;
 if ( ! ( mask & KADM5_POLICY_TL_DATA ) ) {
 pent . n_tl_data = 0 ;
 pent . tl_data = NULL ;
 }
 else {
 pent . n_tl_data = entry -> n_tl_data ;
 pent . tl_data = entry -> tl_data ;
 }
 }
 if ( handle -> api_version >= KADM5_API_VERSION_3 ) {
 if ( ! ( mask & KADM5_PW_MAX_FAILURE ) ) pent . pw_max_fail = 0 ;
 else pent . pw_max_fail = entry -> pw_max_fail ;
 if ( ! ( mask & KADM5_PW_FAILURE_COUNT_INTERVAL ) ) pent . pw_failcnt_interval = 0 ;
 else pent . pw_failcnt_interval = entry -> pw_failcnt_interval ;
 if ( ! ( mask & KADM5_PW_LOCKOUT_DURATION ) ) pent . pw_lockout_duration = 0 ;
 else pent . pw_lockout_duration = entry -> pw_lockout_duration ;
 }
 if ( ( ret = krb5_db_create_policy ( handle -> context , & pent ) ) ) return ret ;
 else return KADM5_OK ;
 }

kadm5_ret_t kadm5_get_policy ( void * server_handle , kadm5_policy_t name , kadm5_policy_ent_t entry ) {
 osa_policy_ent_t t ;
 kadm5_ret_t ret ;
 kadm5_server_handle_t handle = server_handle ;
 memset ( entry , 0 , sizeof ( * entry ) ) ;
 CHECK_HANDLE ( server_handle ) ;
 krb5_clear_error_message ( handle -> context ) ;
 if ( name == ( kadm5_policy_t ) NULL ) return EINVAL ;
 if ( strlen ( name ) == 0 ) return KADM5_BAD_POLICY ;
 ret = krb5_db_get_policy ( handle -> context , name , & t ) ;
 if ( ret == KRB5_KDB_NOENTRY ) return KADM5_UNK_POLICY ;
 else if ( ret ) return ret ;
 if ( ( entry -> policy = strdup ( t -> name ) ) == NULL ) {
 ret = ENOMEM ;
 goto cleanup ;
 }
 entry -> pw_min_life = t -> pw_min_life ;
 entry -> pw_max_life = t -> pw_max_life ;
 entry -> pw_min_length = t -> pw_min_length ;
 entry -> pw_min_classes = t -> pw_min_classes ;
 entry -> pw_history_num = t -> pw_history_num ;
 entry -> policy_refcnt = t -> policy_refcnt ;
 if ( handle -> api_version >= KADM5_API_VERSION_3 ) {
 entry -> pw_max_fail = t -> pw_max_fail ;
 entry -> pw_failcnt_interval = t -> pw_failcnt_interval ;
 entry -> pw_lockout_duration = t -> pw_lockout_duration ;
 }
 if ( handle -> api_version >= KADM5_API_VERSION_4 ) {
 entry -> attributes = t -> attributes ;
 entry -> max_life = t -> max_life ;
 entry -> max_renewable_life = t -> max_renewable_life ;
 if ( t -> allowed_keysalts ) {
 entry -> allowed_keysalts = strdup ( t -> allowed_keysalts ) ;
 if ( ! entry -> allowed_keysalts ) {
 ret = ENOMEM ;
 goto cleanup ;
 }
 }
 ret = copy_tl_data ( t -> n_tl_data , t -> tl_data , & entry -> tl_data ) ;
 if ( ret ) goto cleanup ;
 entry -> n_tl_data = t -> n_tl_data ;
 }
 ret = 0 ;
 cleanup : if ( ret ) kadm5_free_policy_ent ( handle , entry ) ;
 krb5_db_free_policy ( handle -> context , t ) ;
 return ret ;
 }

kadm5_ret_t kadm5_delete_policy ( void * server_handle , kadm5_policy_t name ) {
 kadm5_server_handle_t handle = server_handle ;
 osa_policy_ent_t entry ;
 int ret ;
 CHECK_HANDLE ( server_handle ) ;
 krb5_clear_error_message ( handle -> context ) ;
 if ( name == ( kadm5_policy_t ) NULL ) return EINVAL ;
 if ( strlen ( name ) == 0 ) return KADM5_BAD_POLICY ;
 ret = krb5_db_get_policy ( handle -> context , name , & entry ) ;
 if ( ret == KRB5_KDB_NOENTRY ) return KADM5_UNK_POLICY ;
 else if ( ret ) return ret ;
 if ( entry -> policy_refcnt != 0 ) {
 krb5_db_free_policy ( handle -> context , entry ) ;
 return KADM5_POLICY_REF ;
 }
 krb5_db_free_policy ( handle -> context , entry ) ;
 ret = krb5_db_delete_policy ( handle -> context , name ) ;
 if ( ret == KRB5_KDB_POLICY_REF ) ret = KADM5_POLICY_REF ;
 return ( ret == 0 ) ? KADM5_OK : ret ;
 }

kadm5_ret_t kadm5_modify_policy_internal ( void * server_handle , kadm5_policy_ent_t entry , long mask ) {
 kadm5_server_handle_t handle = server_handle ;
 krb5_tl_data * tl ;
 osa_policy_ent_t p ;
 int ret ;
 size_t len ;
 CHECK_HANDLE ( server_handle ) ;
 if ( ( entry == ( kadm5_policy_ent_t ) NULL ) || ( entry -> policy == NULL ) ) return EINVAL ;
 if ( strlen ( entry -> policy ) == 0 ) return KADM5_BAD_POLICY ;
 if ( ( mask & KADM5_POLICY ) ) return KADM5_BAD_MASK ;
 if ( ( mask & KADM5_POLICY_ALLOWED_KEYSALTS ) && entry -> allowed_keysalts != NULL ) {
 ret = validate_allowed_keysalts ( entry -> allowed_keysalts ) ;
 if ( ret ) return ret ;
 }
 if ( ( mask & KADM5_POLICY_TL_DATA ) ) {
 tl = entry -> tl_data ;
 while ( tl != NULL ) {
 if ( tl -> tl_data_type < 256 ) return KADM5_BAD_TL_TYPE ;
 tl = tl -> tl_data_next ;
 }
 }
 ret = krb5_db_get_policy ( handle -> context , entry -> policy , & p ) ;
 if ( ret == KRB5_KDB_NOENTRY ) return KADM5_UNK_POLICY ;
 else if ( ret ) return ret ;
 if ( ( mask & KADM5_PW_MAX_LIFE ) ) p -> pw_max_life = entry -> pw_max_life ;
 if ( ( mask & KADM5_PW_MIN_LIFE ) ) {
 if ( entry -> pw_min_life > p -> pw_max_life && p -> pw_max_life != 0 ) {
 krb5_db_free_policy ( handle -> context , p ) ;
 return KADM5_BAD_MIN_PASS_LIFE ;
 }
 p -> pw_min_life = entry -> pw_min_life ;
 }
 if ( ( mask & KADM5_PW_MIN_LENGTH ) ) {
 if ( entry -> pw_min_length < MIN_PW_LENGTH ) {
 krb5_db_free_policy ( handle -> context , p ) ;
 return KADM5_BAD_LENGTH ;
 }
 p -> pw_min_length = entry -> pw_min_length ;
 }
 if ( ( mask & KADM5_PW_MIN_CLASSES ) ) {
 if ( entry -> pw_min_classes > MAX_PW_CLASSES || entry -> pw_min_classes < MIN_PW_CLASSES ) {
 krb5_db_free_policy ( handle -> context , p ) ;
 return KADM5_BAD_CLASS ;
 }
 p -> pw_min_classes = entry -> pw_min_classes ;
 }
 if ( ( mask & KADM5_PW_HISTORY_NUM ) ) {
 if ( entry -> pw_history_num < MIN_PW_HISTORY ) {
 krb5_db_free_policy ( handle -> context , p ) ;
 return KADM5_BAD_HISTORY ;
 }
 p -> pw_history_num = entry -> pw_history_num ;
 }
 if ( ( mask & KADM5_REF_COUNT ) ) p -> policy_refcnt = entry -> policy_refcnt ;
 if ( handle -> api_version >= KADM5_API_VERSION_3 ) {
 if ( ( mask & KADM5_PW_MAX_FAILURE ) ) p -> pw_max_fail = entry -> pw_max_fail ;
 if ( ( mask & KADM5_PW_FAILURE_COUNT_INTERVAL ) ) p -> pw_failcnt_interval = entry -> pw_failcnt_interval ;
 if ( ( mask & KADM5_PW_LOCKOUT_DURATION ) ) p -> pw_lockout_duration = entry -> pw_lockout_duration ;
 }
 if ( handle -> api_version >= KADM5_API_VERSION_4 ) {
 if ( ( mask & KADM5_POLICY_ATTRIBUTES ) ) p -> attributes = entry -> attributes ;
 if ( ( mask & KADM5_POLICY_MAX_LIFE ) ) p -> max_life = entry -> max_life ;
 if ( ( mask & KADM5_POLICY_MAX_RLIFE ) ) p -> max_renewable_life = entry -> max_renewable_life ;
 if ( ( mask & KADM5_POLICY_ALLOWED_KEYSALTS ) ) {
 krb5_db_free ( handle -> context , p -> allowed_keysalts ) ;
 p -> allowed_keysalts = NULL ;
 if ( entry -> allowed_keysalts != NULL ) {
 len = strlen ( entry -> allowed_keysalts ) + 1 ;
 p -> allowed_keysalts = krb5_db_alloc ( handle -> context , NULL , len ) ;
 if ( p -> allowed_keysalts == NULL ) {
 ret = ENOMEM ;
 goto cleanup ;
 }
 memcpy ( p -> allowed_keysalts , entry -> allowed_keysalts , len ) ;
 }
 }
 if ( ( mask & KADM5_POLICY_TL_DATA ) ) {
 for ( tl = entry -> tl_data ;
 tl != NULL ;
 tl = tl -> tl_data_next ) {
 ret = krb5_db_update_tl_data ( handle -> context , & p -> n_tl_data , & p -> tl_data , tl ) ;
 if ( ret ) goto cleanup ;
 }
 }
 }
 ret = krb5_db_put_policy ( handle -> context , p ) ;
 cleanup : krb5_db_free_policy ( handle -> context , p ) ;
 return ret ;
 }

