 char newpw [ 1024 ] , dummybuf [ 256 ] ;
 static char prompt1 [ 1024 ] , prompt2 [ 1024 ] ;
 memset ( & princ , 0 , sizeof ( princ ) ) ;
 princ . attributes = 0 ;
 if ( kadmin_parse_princ_args ( argc , argv , & princ , & mask , & pass , & randkey , & ks_tuple , & n_ks_tuple , "add_principal" ) ) {
 kadmin_addprinc_usage ( ) ;
 goto cleanup ;
 }
 retval = krb5_unparse_name ( context , princ . principal , & canon ) ;
 if ( retval ) {
 com_err ( "add_principal" , retval , _ ( "while canonicalizing principal" ) ) ;
 goto cleanup ;
 }
 if ( ! ( mask & KADM5_POLICY ) && ! ( mask & KADM5_POLICY_CLR ) ) {
 if ( ! kadm5_get_policy ( handle , "default" , & defpol ) ) {
 fprintf ( stderr , _ ( "NOTICE: no policy specified for %s;
 " "assigning \"default\"\n" ) , canon ) ;
 princ . policy = "default" ;
 mask |= KADM5_POLICY ;
 kadm5_free_policy_ent ( handle , & defpol ) ;
 }
 else fprintf ( stderr , _ ( "WARNING: no policy specified for %s;
 " "defaulting to no policy\n" ) , canon ) ;
 }
 mask &= ~ KADM5_POLICY_CLR ;
 if ( randkey ) {
 pass = NULL ;
 }
 else if ( pass == NULL ) {
 unsigned int sz = sizeof ( newpw ) - 1 ;
 snprintf ( prompt1 , sizeof ( prompt1 ) , _ ( "Enter password for principal \"%s\"" ) , canon ) ;
 snprintf ( prompt2 , sizeof ( prompt2 ) , _ ( "Re-enter password for principal \"%s\"" ) , canon ) ;
 retval = krb5_read_password ( context , prompt1 , prompt2 , newpw , & sz ) ;
 if ( retval ) {
 com_err ( "add_principal" , retval , _ ( "while reading password for \"%s\"." ) , canon ) ;
 goto cleanup ;
 }
 pass = newpw ;
 }
 mask |= KADM5_PRINCIPAL ;
 retval = create_princ ( & princ , mask , n_ks_tuple , ks_tuple , pass ) ;
 if ( retval == EINVAL && randkey ) {
 prepare_dummy_password ( dummybuf , sizeof ( dummybuf ) ) ;
 princ . attributes |= KRB5_KDB_DISALLOW_ALL_TIX ;
 mask |= KADM5_ATTRIBUTES ;
 pass = dummybuf ;
 retval = create_princ ( & princ , mask , n_ks_tuple , ks_tuple , pass ) ;
 old_style_randkey = 1 ;
 }
 if ( retval ) {
 com_err ( "add_principal" , retval , "while creating \"%s\"." , canon ) ;
 goto cleanup ;
 }
 if ( old_style_randkey ) {
 retval = randkey_princ ( princ . principal , FALSE , n_ks_tuple , ks_tuple ) ;
 if ( retval ) {
 com_err ( "add_principal" , retval , _ ( "while randomizing key for \"%s\"." ) , canon ) ;
 goto cleanup ;
 }
 princ . attributes &= ~ KRB5_KDB_DISALLOW_ALL_TIX ;
 mask = KADM5_ATTRIBUTES ;
 retval = kadm5_modify_principal ( handle , & princ , mask ) ;
 if ( retval ) {
 com_err ( "add_principal" , retval , _ ( "while clearing DISALLOW_ALL_TIX for \"%s\"." ) , canon ) ;
 goto cleanup ;
 }
 }
 printf ( "Principal \"%s\" created.\n" , canon ) ;
 cleanup : krb5_free_principal ( context , princ . principal ) ;
 free ( ks_tuple ) ;
 free ( canon ) ;
 kadmin_free_tl_data ( & princ . n_tl_data , & princ . tl_data ) ;
 }

void mpi_set_ui ( MPI w , unsigned long u ) {
 RESIZE_IF_NEEDED ( w , 1 ) ;
 w -> d [ 0 ] = u ;
 w -> nlimbs = u ? 1 : 0 ;
 w -> sign = 0 ;
 w -> nbits = 0 ;
 w -> flags = 0 ;
 }

METHOD ( asn1_parser_t , iterate , bool , private_asn1_parser_t * this , int * objectID , chunk_t * object ) {
 chunk_t * blob , * blob1 ;
 u_char * start_ptr ;
 u_int level ;
 asn1Object_t obj ;
 * object = chunk_empty ;
 obj = this -> objects [ ++ ( this -> line ) ] ;
 if ( obj . flags & ASN1_EXIT ) {
 return FALSE ;
 }
 if ( obj . flags & ASN1_END ) {
 if ( this -> loopAddr [ obj . level ] && this -> blobs [ obj . level + 1 ] . len > 0 ) {
 this -> line = this -> loopAddr [ obj . level ] ;
 obj = this -> objects [ this -> line ] ;
 }
 else {
 this -> loopAddr [ obj . level ] = 0 ;
 goto end ;
 }
 }
 level = this -> level0 + obj . level ;
 blob = this -> blobs + obj . level ;
 blob1 = blob + 1 ;
 start_ptr = blob -> ptr ;
 if ( ( obj . flags & ASN1_DEF ) && ( blob -> len == 0 || * start_ptr != obj . type ) ) {
 DBG2 ( DBG_ASN , "L%d - %s:" , level , obj . name ) ;
 if ( obj . type & ASN1_CONSTRUCTED ) {
 this -> line ++ ;
 }
 goto end ;
 }
 if ( ( obj . flags & ASN1_OPT ) && ( blob -> len == 0 || * start_ptr != obj . type ) ) {
 do {
 this -> line ++ ;
 }
 while ( ! ( ( this -> objects [ this -> line ] . flags & ASN1_END ) && ( this -> objects [ this -> line ] . level == obj . level ) ) ) ;
 goto end ;
 }
 if ( blob -> len < 2 ) {
 DBG1 ( DBG_ASN , "L%d - %s: ASN.1 object smaller than 2 octets" , level , obj . name ) ;
 this -> success = FALSE ;
 goto end ;
 }
 blob1 -> len = asn1_length ( blob ) ;
 if ( blob1 -> len == ASN1_INVALID_LENGTH ) {
 DBG1 ( DBG_ASN , "L%d - %s: length of ASN.1 object invalid or too large" , level , obj . name ) ;
 this -> success = FALSE ;
 goto end ;
 }
 blob1 -> ptr = blob -> ptr ;
 blob -> ptr += blob1 -> len ;
 blob -> len -= blob1 -> len ;
 if ( obj . flags & ASN1_RAW ) {
 DBG2 ( DBG_ASN , "L%d - %s:" , level , obj . name ) ;
 object -> ptr = start_ptr ;
 object -> len = ( size_t ) ( blob -> ptr - start_ptr ) ;
 goto end ;
 }
 if ( * start_ptr != obj . type && ! ( this -> implicit && this -> line == 0 ) ) {
 DBG2 ( DBG_ASN , "L%d - %s: ASN1 tag 0x%02x expected, but is 0x%02x" , level , obj . name , obj . type , * start_ptr ) ;
 DBG3 ( DBG_ASN , "%b" , start_ptr , ( u_int ) ( blob -> ptr - start_ptr ) ) ;
 this -> success = FALSE ;
 goto end ;
 }
 DBG2 ( DBG_ASN , "L%d - %s:" , level , obj . name ) ;
 if ( obj . flags & ASN1_LOOP ) {
 if ( blob1 -> len > 0 ) {
 this -> loopAddr [ obj . level ] = this -> line + 1 ;
 }
 else {
 do {
 this -> line ++ ;
 }
 while ( ! ( ( this -> objects [ this -> line ] . flags & ASN1_END ) && ( this -> objects [ this -> line ] . level == obj . level ) ) ) ;
 goto end ;
 }
 }
 if ( obj . flags & ASN1_OBJ ) {
 object -> ptr = start_ptr ;
 object -> len = ( size_t ) ( blob -> ptr - start_ptr ) ;
 if ( this -> private ) {
 DBG4 ( DBG_ASN , "%B" , object ) ;
 }
 else {
 DBG3 ( DBG_ASN , "%B" , object ) ;
 }
 }
 else if ( obj . flags & ASN1_BODY ) {
 * object = * blob1 ;
 asn1_debug_simple_object ( * object , obj . type , this -> private ) ;
 }
 end : * objectID = this -> line ;
 return this -> success ;
 }

