 else ahlog ( AH , 1 , "creating %s \"%s\"\n" , te -> desc , te -> tag ) ;
 _printTocEntry ( AH , te , false , false ) ;
 defnDumped = true ;
 if ( strcmp ( te -> desc , "TABLE" ) == 0 ) {
