static void decrypt ( MPI output , MPI a , MPI b , ELG_secret_key * skey ) {
 MPI t1 = mpi_alloc_secure ( mpi_get_nlimbs ( skey -> p ) ) ;
 mpi_normalize ( a ) ;
 mpi_normalize ( b ) ;
 mpi_powm ( t1 , a , skey -> x , skey -> p ) ;
 mpi_invm ( t1 , t1 , skey -> p ) ;
 mpi_mulm ( output , b , t1 , skey -> p ) ;
 # if 0 if ( DBG_CIPHER ) {
 log_mpidump ( "elg decrypted x= " , skey -> x ) ;
 log_mpidump ( "elg decrypted p= " , skey -> p ) ;
 log_mpidump ( "elg decrypted a= " , a ) ;
 log_mpidump ( "elg decrypted b= " , b ) ;
 log_mpidump ( "elg decrypted M= " , output ) ;
 }
 # endif mpi_free ( t1 ) ;
 }

static inline void vmsvga_fill_rect ( struct vmsvga_state_s * s , uint32_t c , int x , int y , int w , int h ) {
 DisplaySurface * surface = qemu_console_surface ( s -> vga . con ) ;
 int bypl = surface_stride ( surface ) ;
 int width = surface_bytes_per_pixel ( surface ) * w ;
 int line = h ;
 int column ;
 uint8_t * fst ;
 uint8_t * dst ;
 uint8_t * src ;
 uint8_t col [ 4 ] ;
 col [ 0 ] = c ;
 col [ 1 ] = c >> 8 ;
 col [ 2 ] = c >> 16 ;
 col [ 3 ] = c >> 24 ;
 fst = s -> vga . vram_ptr + surface_bytes_per_pixel ( surface ) * x + bypl * y ;
 if ( line -- ) {
 dst = fst ;
 src = col ;
 for ( column = width ;
 column > 0 ;
 column -- ) {
 * ( dst ++ ) = * ( src ++ ) ;
 if ( src - col == surface_bytes_per_pixel ( surface ) ) {
 src = col ;
 }
 }
 dst = fst ;
 for ( ;
 line > 0 ;
 line -- ) {
 dst += bypl ;
 memcpy ( dst , fst , width ) ;
 }
 }
 vmsvga_update_rect_delayed ( s , x , y , w , h ) ;
 }

static inline void vmsvga_copy_rect ( struct vmsvga_state_s * s , int x0 , int y0 , int x1 , int y1 , int w , int h ) {
 DisplaySurface * surface = qemu_console_surface ( s -> vga . con ) ;
 uint8_t * vram = s -> vga . vram_ptr ;
 int bypl = surface_stride ( surface ) ;
 int bypp = surface_bytes_per_pixel ( surface ) ;
 int width = bypp * w ;
 int line = h ;
 uint8_t * ptr [ 2 ] ;
 if ( y1 > y0 ) {
 ptr [ 0 ] = vram + bypp * x0 + bypl * ( y0 + h - 1 ) ;
 ptr [ 1 ] = vram + bypp * x1 + bypl * ( y1 + h - 1 ) ;
 for ( ;
 line > 0 ;
 line -- , ptr [ 0 ] -= bypl , ptr [ 1 ] -= bypl ) {
 memmove ( ptr [ 1 ] , ptr [ 0 ] , width ) ;
 }
 }
 else {
 ptr [ 0 ] = vram + bypp * x0 + bypl * y0 ;
 ptr [ 1 ] = vram + bypp * x1 + bypl * y1 ;
 for ( ;
 line > 0 ;
 line -- , ptr [ 0 ] += bypl , ptr [ 1 ] += bypl ) {
 memmove ( ptr [ 1 ] , ptr [ 0 ] , width ) ;
 }
 }
 vmsvga_update_rect_delayed ( s , x1 , y1 , w , h ) ;
 }

