 }
 rr -> length = 0 ;
 RECORD_LAYER_reset_packet_length ( & s -> rlayer ) ;
 goto again ;
 }
 if ( ! dtls1_process_record ( s ) ) {
 rr -> length = 0 ;
 RECORD_LAYER_reset_packet_length ( & s -> rlayer ) ;
 goto again ;
 }
