 char * object = NULL ;
 char * vals = NULL , * query = NULL , * cond_char = NULL ;
 time_t now = time ( NULL ) ;
 char * user_name = NULL ;
 MYSQL_RES * result = NULL ;
 MYSQL_ROW row ;
 if ( ! job_cond || ! job ) {
 error ( "we need something to change" ) ;
