 }
 query = xstrdup_printf ( "select job_db_inx, id_job, time_submit, " "id_user " "from \"%s_%s\" where deleted=0 " "&& id_job=%u " "order by time_submit desc limit 1;
" , job_cond -> cluster , job_table , job_cond -> job_id ) ;
 if ( debug_flags & DEBUG_FLAG_DB_JOB ) DB_DEBUG ( mysql_conn -> conn , "query\n%s" , query ) ;
 if ( ! ( result = mysql_db_query_ret ( mysql_conn , query , 0 ) ) ) {
 xfree ( vals ) ;
 xfree ( query ) ;
 return NULL ;
 }
 if ( ( row = mysql_fetch_row ( result ) ) ) {
 char tmp_char [ 25 ] ;
 time_t time_submit = atol ( row [ 2 ] ) ;
 if ( ( uid != atoi ( row [ 3 ] ) ) && ! is_user_min_admin_level ( mysql_conn , uid , SLURMDB_ADMIN_OPERATOR ) ) {
