 }
 slurm_make_time_str ( & time_submit , tmp_char , sizeof ( tmp_char ) ) ;
 xstrfmtcat ( cond_char , "job_db_inx=%s" , row [ 0 ] ) ;
 object = xstrdup_printf ( "%s submitted at %s" , row [ 1 ] , tmp_char ) ;
