 xfree ( vals ) ;
 xfree ( query ) ;
 mysql_free_result ( result ) ;
 return NULL ;
 }
 xfree ( query ) ;
 user_name = uid_to_string ( ( uid_t ) uid ) ;
 rc = modify_common ( mysql_conn , DBD_MODIFY_JOB , now , user_name , job_table , cond_char , vals , job_cond -> cluster ) ;
 xfree ( user_name ) ;
 xfree ( cond_char ) ;
 xfree ( vals ) ;
