 ( void ) mysql_db_query ( mysql_conn , query ) ;
 xfree ( query ) ;
 }
 else slurm_mutex_unlock ( & rollup_lock ) ;
 if ( ! job_ptr -> db_index ) {
 if ( ! ( job_ptr -> db_index = _get_db_index ( mysql_conn , submit_time , job_ptr -> job_id , job_ptr -> assoc_id ) ) ) {
