 iax2_info -> timestamp = longts ;
 if ( iax2_tree ) {
 item = proto_tree_add_time ( iax2_tree , hf_iax2_absts , NULL , 0 , 0 , & iax_packet -> abstime ) ;
 PROTO_ITEM_SET_GENERATED ( item ) ;
 ts = pinfo -> fd -> abs_ts ;
