 if ( ( child -> ruleset == NULL ) && ( parent -> ruleset == NULL ) ) {
 # ifdef DEBUG_CONF ap_log_perror ( APLOG_MARK , APLOG_STARTUP | APLOG_NOERRNO , 0 , mp , "No rules in this context." ) ;
