 # endif merged -> ruleset = msre_ruleset_create ( parent -> ruleset -> engine , mp ) ;
 copy_rules ( mp , parent -> ruleset , merged -> ruleset , child -> rule_exceptions ) ;
 }
 else if ( parent -> ruleset == NULL ) {
 # ifdef DEBUG_CONF ap_log_perror ( APLOG_MARK , APLOG_STARTUP | APLOG_NOERRNO , 0 , mp , "Using child rules in this context." ) ;
 # endif merged -> ruleset = msre_ruleset_create ( child -> ruleset -> engine , mp ) ;
