int get_file_params_count_resume ( char * * params , int paramcount ) {
 int pos , best ;
 if ( * params [ 0 ] == '"' ) {
 for ( pos = 0 ;
 pos < paramcount - 2 ;
 pos ++ ) {
 if ( params [ pos ] [ strlen ( params [ pos ] ) - 1 ] == '"' && get_params_match_resume ( params , pos + 1 ) ) return pos + 1 ;
 }
 }
 best = paramcount - 2 ;
 for ( pos = paramcount - 2 ;
 pos > 0 ;
 pos -- ) {
 if ( get_params_match_resume ( params , pos ) ) best = pos ;
 }
 return best ;
 }

static int ivr_read_header ( AVFormatContext * s ) {
 unsigned tag , type , len , tlen , value ;
 int i , j , n , count , nb_streams = 0 , ret ;
 uint8_t key [ 256 ] , val [ 256 ] ;
 AVIOContext * pb = s -> pb ;
 AVStream * st ;
 int64_t pos , offset , temp ;
 pos = avio_tell ( pb ) ;
 tag = avio_rl32 ( pb ) ;
 if ( tag == MKTAG ( '.' , 'R' , '1' , 'M' ) ) {
 if ( avio_rb16 ( pb ) != 1 ) return AVERROR_INVALIDDATA ;
 if ( avio_r8 ( pb ) != 1 ) return AVERROR_INVALIDDATA ;
 len = avio_rb32 ( pb ) ;
 avio_skip ( pb , len ) ;
 avio_skip ( pb , 5 ) ;
 temp = avio_rb64 ( pb ) ;
 while ( ! avio_feof ( pb ) && temp ) {
 offset = temp ;
 temp = avio_rb64 ( pb ) ;
 }
 avio_skip ( pb , offset - avio_tell ( pb ) ) ;
 if ( avio_r8 ( pb ) != 1 ) return AVERROR_INVALIDDATA ;
 len = avio_rb32 ( pb ) ;
 avio_skip ( pb , len ) ;
 if ( avio_r8 ( pb ) != 2 ) return AVERROR_INVALIDDATA ;
 avio_skip ( pb , 16 ) ;
 pos = avio_tell ( pb ) ;
 tag = avio_rl32 ( pb ) ;
 }
 if ( tag != MKTAG ( '.' , 'R' , 'E' , 'C' ) ) return AVERROR_INVALIDDATA ;
 if ( avio_r8 ( pb ) != 0 ) return AVERROR_INVALIDDATA ;
 count = avio_rb32 ( pb ) ;
 for ( i = 0 ;
 i < count ;
 i ++ ) {
 if ( avio_feof ( pb ) ) return AVERROR_INVALIDDATA ;
 type = avio_r8 ( pb ) ;
 tlen = avio_rb32 ( pb ) ;
 avio_get_str ( pb , tlen , key , sizeof ( key ) ) ;
 len = avio_rb32 ( pb ) ;
 if ( type == 5 ) {
 avio_get_str ( pb , len , val , sizeof ( val ) ) ;
 av_log ( s , AV_LOG_DEBUG , "%s = '%s'\n" , key , val ) ;
 }
 else if ( type == 4 ) {
 av_log ( s , AV_LOG_DEBUG , "%s = '0x" , key ) ;
 for ( j = 0 ;
 j < len ;
 j ++ ) av_log ( s , AV_LOG_DEBUG , "%X" , avio_r8 ( pb ) ) ;
 av_log ( s , AV_LOG_DEBUG , "'\n" ) ;
 }
 else if ( len == 4 && type == 3 && ! strncmp ( key , "StreamCount" , tlen ) ) {
 nb_streams = value = avio_rb32 ( pb ) ;
 }
 else if ( len == 4 && type == 3 ) {
 value = avio_rb32 ( pb ) ;
 av_log ( s , AV_LOG_DEBUG , "%s = %d\n" , key , value ) ;
 }
 else {
 av_log ( s , AV_LOG_DEBUG , "Skipping unsupported key: %s\n" , key ) ;
 avio_skip ( pb , len ) ;
 }
 }
 for ( n = 0 ;
 n < nb_streams ;
 n ++ ) {
 st = avformat_new_stream ( s , NULL ) ;
 if ( ! st ) return AVERROR ( ENOMEM ) ;
 st -> priv_data = ff_rm_alloc_rmstream ( ) ;
 if ( ! st -> priv_data ) return AVERROR ( ENOMEM ) ;
 if ( avio_r8 ( pb ) != 1 ) return AVERROR_INVALIDDATA ;
 count = avio_rb32 ( pb ) ;
 for ( i = 0 ;
 i < count ;
 i ++ ) {
 if ( avio_feof ( pb ) ) return AVERROR_INVALIDDATA ;
 type = avio_r8 ( pb ) ;
 tlen = avio_rb32 ( pb ) ;
 avio_get_str ( pb , tlen , key , sizeof ( key ) ) ;
 len = avio_rb32 ( pb ) ;
 if ( type == 5 ) {
 avio_get_str ( pb , len , val , sizeof ( val ) ) ;
 av_log ( s , AV_LOG_DEBUG , "%s = '%s'\n" , key , val ) ;
 }
 else if ( type == 4 && ! strncmp ( key , "OpaqueData" , tlen ) ) {
 ret = ffio_ensure_seekback ( pb , 4 ) ;
 if ( ret < 0 ) return ret ;
 if ( avio_rb32 ( pb ) == MKBETAG ( 'M' , 'L' , 'T' , 'I' ) ) {
 ret = rm_read_multi ( s , pb , st , NULL ) ;
 }
 else {
 avio_seek ( pb , - 4 , SEEK_CUR ) ;
 ret = ff_rm_read_mdpr_codecdata ( s , pb , st , st -> priv_data , len , NULL ) ;
 }
 if ( ret < 0 ) return ret ;
 }
 else if ( type == 4 ) {
 int j ;
 av_log ( s , AV_LOG_DEBUG , "%s = '0x" , key ) ;
 for ( j = 0 ;
 j < len ;
 j ++ ) av_log ( s , AV_LOG_DEBUG , "%X" , avio_r8 ( pb ) ) ;
 av_log ( s , AV_LOG_DEBUG , "'\n" ) ;
 }
 else if ( len == 4 && type == 3 && ! strncmp ( key , "Duration" , tlen ) ) {
 st -> duration = avio_rb32 ( pb ) ;
 }
 else if ( len == 4 && type == 3 ) {
 value = avio_rb32 ( pb ) ;
 av_log ( s , AV_LOG_DEBUG , "%s = %d\n" , key , value ) ;
 }
 else {
 av_log ( s , AV_LOG_DEBUG , "Skipping unsupported key: %s\n" , key ) ;
 avio_skip ( pb , len ) ;
 }
 }
 }
 if ( avio_r8 ( pb ) != 6 ) return AVERROR_INVALIDDATA ;
 avio_skip ( pb , 12 ) ;
 avio_skip ( pb , avio_rb64 ( pb ) + pos - avio_tell ( s -> pb ) ) ;
 if ( avio_r8 ( pb ) != 8 ) return AVERROR_INVALIDDATA ;
 avio_skip ( pb , 8 ) ;
 return 0 ;
 }

static int cert_status_cb ( SSL * s , void * arg ) {
 tlsextstatusctx * srctx = arg ;
 BIO * err = srctx -> err ;
 char * host , * port , * path ;
 int use_ssl ;
 unsigned char * rspder = NULL ;
 int rspderlen ;
 STACK_OF ( OPENSSL_STRING ) * aia = NULL ;
 X509 * x = NULL ;
 X509_STORE_CTX inctx ;
 X509_OBJECT obj ;
 OCSP_REQUEST * req = NULL ;
 OCSP_RESPONSE * resp = NULL ;
 OCSP_CERTID * id = NULL ;
 STACK_OF ( X509_EXTENSION ) * exts ;
 int ret = SSL_TLSEXT_ERR_NOACK ;
 int i ;
 # if 0 STACK_OF ( OCSP_RESPID ) * ids ;
 SSL_get_tlsext_status_ids ( s , & ids ) ;
 BIO_printf ( err , "cert_status: received %d ids\n" , sk_OCSP_RESPID_num ( ids ) ) ;
 # endif if ( srctx -> verbose ) BIO_puts ( err , "cert_status: callback called\n" ) ;
 x = SSL_get_certificate ( s ) ;
 aia = X509_get1_ocsp ( x ) ;
 if ( aia ) {
 if ( ! OCSP_parse_url ( sk_OPENSSL_STRING_value ( aia , 0 ) , & host , & port , & path , & use_ssl ) ) {
 BIO_puts ( err , "cert_status: can't parse AIA URL\n" ) ;
 goto err ;
 }
 if ( srctx -> verbose ) BIO_printf ( err , "cert_status: AIA URL: %s\n" , sk_OPENSSL_STRING_value ( aia , 0 ) ) ;
 }
 else {
 if ( ! srctx -> host ) {
 BIO_puts ( srctx -> err , "cert_status: no AIA and no default responder URL\n" ) ;
 goto done ;
 }
 host = srctx -> host ;
 path = srctx -> path ;
 port = srctx -> port ;
 use_ssl = srctx -> use_ssl ;
 }
 if ( ! X509_STORE_CTX_init ( & inctx , SSL_CTX_get_cert_store ( SSL_get_SSL_CTX ( s ) ) , NULL , NULL ) ) goto err ;
 if ( X509_STORE_get_by_subject ( & inctx , X509_LU_X509 , X509_get_issuer_name ( x ) , & obj ) <= 0 ) {
 BIO_puts ( err , "cert_status: Can't retrieve issuer certificate.\n" ) ;
 X509_STORE_CTX_cleanup ( & inctx ) ;
 goto done ;
 }
 req = OCSP_REQUEST_new ( ) ;
 if ( ! req ) goto err ;
 id = OCSP_cert_to_id ( NULL , x , obj . data . x509 ) ;
 X509_free ( obj . data . x509 ) ;
 X509_STORE_CTX_cleanup ( & inctx ) ;
 if ( ! id ) goto err ;
 if ( ! OCSP_request_add0_id ( req , id ) ) goto err ;
 id = NULL ;
 SSL_get_tlsext_status_exts ( s , & exts ) ;
 for ( i = 0 ;
 i < sk_X509_EXTENSION_num ( exts ) ;
 i ++ ) {
 X509_EXTENSION * ext = sk_X509_EXTENSION_value ( exts , i ) ;
 if ( ! OCSP_REQUEST_add_ext ( req , ext , - 1 ) ) goto err ;
 }
 resp = process_responder ( err , req , host , path , port , use_ssl , NULL , srctx -> timeout ) ;
 if ( ! resp ) {
 BIO_puts ( err , "cert_status: error querying responder\n" ) ;
 goto done ;
 }
 rspderlen = i2d_OCSP_RESPONSE ( resp , & rspder ) ;
 if ( rspderlen <= 0 ) goto err ;
 SSL_set_tlsext_status_ocsp_resp ( s , rspder , rspderlen ) ;
 if ( srctx -> verbose ) {
 BIO_puts ( err , "cert_status: ocsp response sent:\n" ) ;
 OCSP_RESPONSE_print ( err , resp , 2 ) ;
 }
 ret = SSL_TLSEXT_ERR_OK ;
 done : if ( ret != SSL_TLSEXT_ERR_OK ) ERR_print_errors ( err ) ;
 if ( aia ) {
 OPENSSL_free ( host ) ;
 OPENSSL_free ( path ) ;
 OPENSSL_free ( port ) ;
 X509_email_free ( aia ) ;
 }
 if ( id ) OCSP_CERTID_free ( id ) ;
 if ( req ) OCSP_REQUEST_free ( req ) ;
 if ( resp ) OCSP_RESPONSE_free ( resp ) ;
 return ret ;
 err : ret = SSL_TLSEXT_ERR_ALERT_FATAL ;
 goto done ;
 }
