static int ngsniffer_process_record ( wtap * wth , gboolean is_random , guint * padding , struct wtap_pkthdr * phdr , Buffer * buf , int * err , gchar * * err_info ) {
 ngsniffer_t * ngsniffer ;
 char record_type [ 2 ] ;
 char record_length [ 4 ] ;
 guint16 type , length ;
 struct frame2_rec frame2 ;
 struct frame4_rec frame4 ;
 struct frame6_rec frame6 ;
 guint16 time_low , time_med , true_size , size ;
 guint8 time_high , time_day ;
 guint64 t , tsecs , tpsecs ;
 if ( ! ng_read_bytes_or_eof ( wth , record_type , 2 , is_random , err , err_info ) ) {
 if ( * err != 0 ) return - 1 ;
 return REC_EOF ;
 }
 if ( ! ng_read_bytes ( wth , record_length , 4 , is_random , err , err_info ) ) return - 1 ;
 type = pletoh16 ( record_type ) ;
 length = pletoh16 ( record_length ) ;
 ngsniffer = ( ngsniffer_t * ) wth -> priv ;
 switch ( type ) {
 case REC_FRAME2 : if ( ngsniffer -> network == NETWORK_ATM ) {
 * err = WTAP_ERR_BAD_FILE ;
 * err_info = g_strdup ( "ngsniffer: REC_FRAME2 record in an ATM Sniffer file" ) ;
 return - 1 ;
 }
 if ( ! ng_read_bytes ( wth , & frame2 , ( unsigned int ) sizeof frame2 , is_random , err , err_info ) ) return - 1 ;
 time_low = pletoh16 ( & frame2 . time_low ) ;
 time_med = pletoh16 ( & frame2 . time_med ) ;
 time_high = frame2 . time_high ;
 time_day = frame2 . time_day ;
 size = pletoh16 ( & frame2 . size ) ;
 true_size = pletoh16 ( & frame2 . true_size ) ;
 length -= sizeof frame2 ;
 set_pseudo_header_frame2 ( wth , & phdr -> pseudo_header , & frame2 ) ;
 break ;
 case REC_FRAME4 : if ( ngsniffer -> network != NETWORK_ATM ) {
 * err = WTAP_ERR_BAD_FILE ;
 * err_info = g_strdup ( "ngsniffer: REC_FRAME4 record in a non-ATM Sniffer file" ) ;
 return - 1 ;
 }
 if ( ! ng_read_bytes ( wth , & frame4 , ( unsigned int ) sizeof frame4 , is_random , err , err_info ) ) return - 1 ;
 time_low = pletoh16 ( & frame4 . time_low ) ;
 time_med = pletoh16 ( & frame4 . time_med ) ;
 time_high = frame4 . time_high ;
 time_day = frame4 . time_day ;
 size = pletoh16 ( & frame4 . size ) ;
 true_size = pletoh16 ( & frame4 . true_size ) ;
 if ( ngsniffer -> maj_vers >= 5 ) length -= sizeof frame4 ;
 else {
 if ( ngsniffer -> min_vers >= 95 ) length -= sizeof frame2 ;
 else length -= sizeof frame4 ;
 }
 set_pseudo_header_frame4 ( & phdr -> pseudo_header , & frame4 ) ;
 break ;
 case REC_FRAME6 : if ( ! ng_read_bytes ( wth , & frame6 , ( unsigned int ) sizeof frame6 , is_random , err , err_info ) ) return - 1 ;
 time_low = pletoh16 ( & frame6 . time_low ) ;
 time_med = pletoh16 ( & frame6 . time_med ) ;
 time_high = frame6 . time_high ;
 time_day = frame6 . time_day ;
 size = pletoh16 ( & frame6 . size ) ;
 true_size = pletoh16 ( & frame6 . true_size ) ;
 length -= sizeof frame6 ;
 set_pseudo_header_frame6 ( wth , & phdr -> pseudo_header , & frame6 ) ;
 break ;
 case REC_EOF : * err = 0 ;
 return REC_EOF ;
 default : if ( padding != NULL ) {
 * padding = length ;
 }
 return type ;
 }
 if ( size > length ) {
 * err = WTAP_ERR_BAD_FILE ;
 * err_info = g_strdup ( "ngsniffer: Record length is less than packet size" ) ;
 return - 1 ;
 }
 if ( padding != NULL ) {
 * padding = length - size ;
 }
 phdr -> rec_type = REC_TYPE_PACKET ;
 phdr -> presence_flags = true_size ? WTAP_HAS_TS | WTAP_HAS_CAP_LEN : WTAP_HAS_TS ;
 phdr -> len = true_size ? true_size : size ;
 phdr -> caplen = size ;
 ws_buffer_assure_space ( buf , size ) ;
 if ( ! ng_read_bytes ( wth , ws_buffer_start_ptr ( buf ) , size , is_random , err , err_info ) ) return - 1 ;
 phdr -> pkt_encap = fix_pseudo_header ( wth -> file_encap , buf , length , & phdr -> pseudo_header ) ;
 t = ( ( ( guint64 ) time_high ) << 32 ) | ( ( ( guint64 ) time_med ) << 16 ) | time_low ;
 t *= ngsniffer -> timeunit ;
 tsecs = t / G_GUINT64_CONSTANT ( 1000000000000 ) ;
 tpsecs = t - tsecs * G_GUINT64_CONSTANT ( 1000000000000 ) ;
 tsecs += time_day * 86400 ;
 tsecs += ngsniffer -> start ;
 phdr -> ts . secs = ( time_t ) tsecs ;
 phdr -> ts . nsecs = ( int ) ( tpsecs / 1000 ) ;
 return type ;
 }

static block_t * Encode ( encoder_t * p_enc , picture_t * p_pic ) {
 encoder_sys_t * p_sys = p_enc -> p_sys ;
 block_t * p_block , * p_output_chain = NULL ;
 SchroFrame * p_frame ;
 bool b_go = true ;
 if ( ! p_pic ) {
 if ( ! p_sys -> started || p_sys -> b_eos_pulled ) return NULL ;
 if ( ! p_sys -> b_eos_signalled ) {
 p_sys -> b_eos_signalled = 1 ;
 schro_encoder_end_of_stream ( p_sys -> p_schro ) ;
 }
 }
 else {
 p_sys -> p_format -> interlaced = ! p_pic -> b_progressive ;
 p_sys -> p_format -> top_field_first = p_pic -> b_top_field_first ;
 if ( p_sys -> b_auto_field_coding ) schro_encoder_setting_set_double ( p_sys -> p_schro , "interlaced_coding" , ! p_pic -> b_progressive ) ;
 }
 if ( ! p_sys -> started ) {
 date_t date ;
 if ( p_pic -> format . i_chroma != p_enc -> fmt_in . i_codec ) {
 char chroma_in [ 5 ] , chroma_out [ 5 ] ;
 vlc_fourcc_to_char ( p_pic -> format . i_chroma , chroma_in ) ;
 chroma_in [ 4 ] = '\0' ;
 chroma_out [ 4 ] = '\0' ;
 vlc_fourcc_to_char ( p_enc -> fmt_in . i_codec , chroma_out ) ;
 msg_Warn ( p_enc , "Resetting chroma from %s to %s" , chroma_out , chroma_in ) ;
 if ( ! SetEncChromaFormat ( p_enc , p_pic -> format . i_chroma ) ) {
 msg_Err ( p_enc , "Could not reset chroma format to %s" , chroma_in ) ;
 return NULL ;
 }
 }
 date_Init ( & date , p_enc -> fmt_in . video . i_frame_rate , p_enc -> fmt_in . video . i_frame_rate_base ) ;
 date_Increment ( & date , 1 ) ;
 p_sys -> i_pts_offset = date_Get ( & date ) ;
 if ( schro_encoder_setting_get_double ( p_sys -> p_schro , "interlaced_coding" ) > 0.0 ) {
 date_Set ( & date , 0 ) ;
 date_Increment ( & date , 1 ) ;
 p_sys -> i_field_time = date_Get ( & date ) / 2 ;
 }
 schro_video_format_set_std_signal_range ( p_sys -> p_format , SCHRO_SIGNAL_RANGE_8BIT_VIDEO ) ;
 schro_encoder_set_video_format ( p_sys -> p_schro , p_sys -> p_format ) ;
 schro_encoder_start ( p_sys -> p_schro ) ;
 p_sys -> started = 1 ;
 }
 if ( ! p_sys -> b_eos_signalled ) {
 picture_Hold ( p_pic ) ;
 p_frame = CreateSchroFrameFromInputPic ( p_enc , p_pic ) ;
 if ( ! p_frame ) return NULL ;
 schro_encoder_push_frame ( p_sys -> p_schro , p_frame ) ;
 StorePicturePTS ( p_enc , p_sys -> i_input_picnum , p_pic -> date ) ;
 p_sys -> i_input_picnum ++ ;
 p_block = block_Alloc ( 1 ) ;
 if ( ! p_block ) return NULL ;
 p_block -> i_dts = p_pic -> date - p_sys -> i_pts_offset ;
 block_FifoPut ( p_sys -> p_dts_fifo , p_block ) ;
 p_block = NULL ;
 if ( schro_encoder_setting_get_double ( p_sys -> p_schro , "interlaced_coding" ) > 0.0 ) {
 StorePicturePTS ( p_enc , p_sys -> i_input_picnum , p_pic -> date + p_sys -> i_field_time ) ;
 p_sys -> i_input_picnum ++ ;
 p_block = block_Alloc ( 1 ) ;
 if ( ! p_block ) return NULL ;
 p_block -> i_dts = p_pic -> date - p_sys -> i_pts_offset + p_sys -> i_field_time ;
 block_FifoPut ( p_sys -> p_dts_fifo , p_block ) ;
 p_block = NULL ;
 }
 }
 do {
 SchroStateEnum state ;
 state = schro_encoder_wait ( p_sys -> p_schro ) ;
 switch ( state ) {
 case SCHRO_STATE_NEED_FRAME : b_go = false ;
 break ;
 case SCHRO_STATE_AGAIN : break ;
 case SCHRO_STATE_END_OF_STREAM : p_sys -> b_eos_pulled = 1 ;
 b_go = false ;
 break ;
 case SCHRO_STATE_HAVE_BUFFER : {
 SchroBuffer * p_enc_buf ;
 uint32_t u_pic_num ;
 int i_presentation_frame ;
 p_enc_buf = schro_encoder_pull ( p_sys -> p_schro , & i_presentation_frame ) ;
 p_block = block_Alloc ( p_enc_buf -> length ) ;
 if ( ! p_block ) return NULL ;
 memcpy ( p_block -> p_buffer , p_enc_buf -> data , p_enc_buf -> length ) ;
 schro_buffer_unref ( p_enc_buf ) ;
 if ( 0 == p_block -> p_buffer [ 4 ] ) {
 p_block -> i_flags |= BLOCK_FLAG_TYPE_I ;
 if ( ! p_enc -> fmt_out . p_extra ) {
 const uint8_t eos [ ] = {
 'B' , 'B' , 'C' , 'D' , 0x10 , 0 , 0 , 0 , 13 , 0 , 0 , 0 , 0 }
 ;
 uint32_t len = GetDWBE ( p_block -> p_buffer + 5 ) ;
 p_enc -> fmt_out . p_extra = malloc ( len + sizeof ( eos ) ) ;
 if ( ! p_enc -> fmt_out . p_extra ) return NULL ;
 memcpy ( p_enc -> fmt_out . p_extra , p_block -> p_buffer , len ) ;
 memcpy ( ( uint8_t * ) p_enc -> fmt_out . p_extra + len , eos , sizeof ( eos ) ) ;
 SetDWBE ( ( uint8_t * ) p_enc -> fmt_out . p_extra + len + sizeof ( eos ) - 4 , len ) ;
 p_enc -> fmt_out . i_extra = len + sizeof ( eos ) ;
 }
 }
 if ( ReadDiracPictureNumber ( & u_pic_num , p_block ) ) {
 block_t * p_dts_block = block_FifoGet ( p_sys -> p_dts_fifo ) ;
 p_block -> i_dts = p_dts_block -> i_dts ;
 p_block -> i_pts = GetPicturePTS ( p_enc , u_pic_num ) ;
 block_Release ( p_dts_block ) ;
 block_ChainAppend ( & p_output_chain , p_block ) ;
 }
 else {
 block_ChainAppend ( & p_output_chain , p_block ) ;
 }
 break ;
 }
 default : break ;
 }
 }
 while ( b_go ) ;
 return p_output_chain ;
 }

