 pi -> x < pi -> xend ;
 pi -> x += pi -> xstep - ( pi -> x % pi -> xstep ) ) {
 for ( pi -> rlvlno = pchg -> rlvlnostart , pi -> pirlvl = & pi -> picomp -> pirlvls [ pi -> rlvlno ] ;
 pi -> rlvlno < pi -> picomp -> numrlvls && pi -> rlvlno < pchg -> rlvlnoend ;
 ++ pi -> rlvlno , ++ pi -> pirlvl ) {
