static void voutf ( struct GlobalConfig * config , const char * prefix , const char * fmt , va_list ap ) {
 size_t width = ( 79 - strlen ( prefix ) ) ;
 if ( ! config -> mute ) {
 size_t len ;
 char * ptr ;
 char * print_buffer ;
 print_buffer = curlx_mvaprintf ( fmt , ap ) ;
 if ( ! print_buffer ) return ;
 len = strlen ( print_buffer ) ;
 ptr = print_buffer ;
 while ( len > 0 ) {
 fputs ( prefix , config -> errors ) ;
 if ( len > width ) {
 size_t cut = width - 1 ;
 while ( ! ISSPACE ( ptr [ cut ] ) && cut ) {
 cut -- ;
 }
 if ( 0 == cut ) cut = width - 1 ;
 ( void ) fwrite ( ptr , cut + 1 , 1 , config -> errors ) ;
 fputs ( "\n" , config -> errors ) ;
 ptr += cut + 1 ;
 len -= cut ;
 }
 else {
 fputs ( ptr , config -> errors ) ;
 len = 0 ;
 }
 }
 curl_free ( print_buffer ) ;
 }
 }

static void gx_ttfReader__Read ( ttfReader * self , void * p , int n ) {
 gx_ttfReader * r = ( gx_ttfReader * ) self ;
 const byte * q ;
 if ( ! r -> error ) {
 if ( r -> extra_glyph_index != - 1 ) {
 q = r -> glyph_data . bits . data + r -> pos ;
 r -> error = ( r -> glyph_data . bits . size - r -> pos < n ? gs_note_error ( gs_error_invalidfont ) : 0 ) ;
 if ( r -> error == 0 ) memcpy ( p , q , n ) ;
 }
 else {
 unsigned int cnt ;
 for ( cnt = 0 ;
 cnt < ( uint ) n ;
 cnt += r -> error ) {
 r -> error = r -> pfont -> data . string_proc ( r -> pfont , ( ulong ) r -> pos + cnt , ( ulong ) n - cnt , & q ) ;
 if ( r -> error < 0 ) break ;
 else if ( r -> error == 0 ) {
 memcpy ( ( char * ) p + cnt , q , n - cnt ) ;
 break ;
 }
 else {
 memcpy ( ( char * ) p + cnt , q , r -> error ) ;
 }
 }
 }
 }
 if ( r -> error ) {
 memset ( p , 0 , n ) ;
 return ;
 }
 r -> pos += n ;
 }

