int av_image_fill_pointers ( uint8_t * data [ 4 ] , enum PixelFormat pix_fmt , int height , uint8_t * ptr , const int linesizes [ 4 ] ) {
 int i , total_size , size [ 4 ] , has_plane [ 4 ] ;
