 av_freep ( & pd . buf ) ;
 if ( ! sub_demuxer ) goto error ;
 if ( ! ( ast -> sub_ctx = avformat_alloc_context ( ) ) ) goto error ;
 ast -> sub_ctx -> pb = pb ;
 if ( ff_copy_whiteblacklists ( ast -> sub_ctx , s ) < 0 ) goto error ;
