 # else memcpy ( data + n_data , & color , sizeof ( color ) ) ;
 n_data += sizeof ( pixel_t ) ;
 # endif hextile_enc_cord ( data + n_data , min_x , j , i - min_x , 1 ) ;
 n_data += 2 ;
