void stp_print ( netdissect_options * ndo , const u_char * p , u_int length ) {
 const struct stp_bpdu_ * stp_bpdu ;
 u_int mstp_len ;
 u_int spb_len ;
 stp_bpdu = ( const struct stp_bpdu_ * ) p ;
 if ( length < 4 ) goto trunc ;
 ND_TCHECK ( stp_bpdu -> protocol_id ) ;
 if ( EXTRACT_16BITS ( & stp_bpdu -> protocol_id ) ) {
 ND_PRINT ( ( ndo , "unknown STP version, length %u" , length ) ) ;
 return ;
 }
 ND_TCHECK ( stp_bpdu -> protocol_version ) ;
 ND_PRINT ( ( ndo , "STP %s" , tok2str ( stp_proto_values , "Unknown STP protocol (0x%02x)" , stp_bpdu -> protocol_version ) ) ) ;
 switch ( stp_bpdu -> protocol_version ) {
 case STP_PROTO_REGULAR : case STP_PROTO_RAPID : case STP_PROTO_MSTP : case STP_PROTO_SPB : break ;
 default : return ;
 }
 ND_TCHECK ( stp_bpdu -> bpdu_type ) ;
 ND_PRINT ( ( ndo , ", %s" , tok2str ( stp_bpdu_type_values , "Unknown BPDU Type (0x%02x)" , stp_bpdu -> bpdu_type ) ) ) ;
 switch ( stp_bpdu -> bpdu_type ) {
 case STP_BPDU_TYPE_CONFIG : if ( length < sizeof ( struct stp_bpdu_ ) - 1 ) {
 goto trunc ;
 }
 if ( ! stp_print_config_bpdu ( ndo , stp_bpdu , length ) ) goto trunc ;
 break ;
 case STP_BPDU_TYPE_RSTP : if ( stp_bpdu -> protocol_version == STP_PROTO_RAPID ) {
 if ( length < sizeof ( struct stp_bpdu_ ) ) {
 goto trunc ;
 }
 if ( ! stp_print_config_bpdu ( ndo , stp_bpdu , length ) ) goto trunc ;
 }
 else if ( stp_bpdu -> protocol_version == STP_PROTO_MSTP || stp_bpdu -> protocol_version == STP_PROTO_SPB ) {
 if ( length < STP_BPDU_MSTP_MIN_LEN ) {
 goto trunc ;
 }
 ND_TCHECK ( stp_bpdu -> v1_length ) ;
 if ( stp_bpdu -> v1_length != 0 ) {
 goto trunc ;
 }
 ND_TCHECK_16BITS ( p + MST_BPDU_VER3_LEN_OFFSET ) ;
 mstp_len = EXTRACT_16BITS ( p + MST_BPDU_VER3_LEN_OFFSET ) ;
 mstp_len += 2 ;
 if ( length < ( sizeof ( struct stp_bpdu_ ) + mstp_len ) ) {
 goto trunc ;
 }
 if ( ! stp_print_mstp_bpdu ( ndo , stp_bpdu , length ) ) goto trunc ;
 if ( stp_bpdu -> protocol_version == STP_PROTO_SPB ) {
 spb_len = EXTRACT_16BITS ( p + MST_BPDU_VER3_LEN_OFFSET + mstp_len ) ;
 spb_len += 2 ;
 if ( length < ( sizeof ( struct stp_bpdu_ ) + mstp_len + spb_len ) || spb_len < SPB_BPDU_MIN_LEN ) {
 goto trunc ;
 }
 if ( ! stp_print_spb_bpdu ( ndo , stp_bpdu , ( sizeof ( struct stp_bpdu_ ) + mstp_len ) ) ) goto trunc ;
 }
 }
 break ;
 case STP_BPDU_TYPE_TOPO_CHANGE : break ;
 default : break ;
 }
 return ;
 trunc : ND_PRINT ( ( ndo , "[|stp %d]" , length ) ) ;
 }

static int s_aes_process ( stream_state * ss , stream_cursor_read * pr , stream_cursor_write * pw , bool last ) {
 stream_aes_state * const state = ( stream_aes_state * ) ss ;
 const unsigned char * limit ;
 const long in_size = pr -> limit - pr -> ptr ;
 const long out_size = pw -> limit - pw -> ptr ;
 unsigned char temp [ 16 ] ;
 int status = 0 ;
 if ( in_size > out_size ) {
 limit = pr -> ptr + out_size ;
 status = 1 ;
 }
 else {
 limit = pr -> limit ;
 status = last ? EOFC : 0 ;
 }
 if ( state -> ctx == NULL ) {
 state -> ctx = ( aes_context * ) gs_alloc_bytes_immovable ( state -> memory , sizeof ( aes_context ) , "aes context structure" ) ;
 if ( state -> ctx == NULL ) {
 gs_throw ( gs_error_VMerror , "could not allocate aes context" ) ;
 return ERRC ;
 }
 if ( state -> keylength < 1 || state -> keylength > SAES_MAX_KEYLENGTH ) {
 gs_throw1 ( gs_error_rangecheck , "invalid aes key length (%d bytes)" , state -> keylength ) ;
 return ERRC ;
 }
 aes_setkey_dec ( state -> ctx , state -> key , state -> keylength * 8 ) ;
 }
 if ( ! state -> initialized ) {
 if ( in_size < 16 ) return 0 ;
 memcpy ( state -> iv , pr -> ptr + 1 , 16 ) ;
 state -> initialized = 1 ;
 pr -> ptr += 16 ;
 }
 while ( pr -> ptr + 16 <= limit ) {
 aes_crypt_cbc ( state -> ctx , AES_DECRYPT , 16 , state -> iv , pr -> ptr + 1 , temp ) ;
 pr -> ptr += 16 ;
 if ( last && pr -> ptr == pr -> limit ) {
 int pad ;
 if ( state -> use_padding ) {
 pad = temp [ 15 ] ;
 if ( pad < 1 || pad > 16 ) {
 gs_warn1 ( "invalid aes padding byte (0x%02x)" , ( unsigned char ) pad ) ;
 pad = 0 ;
 }
 }
 else {
 pad = 0 ;
 }
 memcpy ( pw -> ptr + 1 , temp , 16 - pad ) ;
 pw -> ptr += 16 - pad ;
 return EOFC ;
 }
 memcpy ( pw -> ptr + 1 , temp , 16 ) ;
 pw -> ptr += 16 ;
 }
 if ( status == EOFC ) {
 gs_throw ( gs_error_rangecheck , "aes stream isn't a multiple of 16 bytes" ) ;
 return 0 ;
 }
 return status ;
 }

void aes_crypt_ecb ( aes_context * ctx , int mode , const unsigned char input [ 16 ] , unsigned char output [ 16 ] ) {
 int i ;
 unsigned long * RK , X0 , X1 , X2 , X3 , Y0 , Y1 , Y2 , Y3 ;
 # if defined ( XYSSL_PADLOCK_C ) && defined ( XYSSL_HAVE_X86 ) if ( padlock_supports ( PADLOCK_ACE ) ) {
 if ( padlock_xcryptecb ( ctx , mode , input , output ) == 0 ) return ;
 }
 # endif RK = ctx -> rk ;
 GET_ULONG_LE ( X0 , input , 0 ) ;
 X0 ^= * RK ++ ;
 GET_ULONG_LE ( X1 , input , 4 ) ;
 X1 ^= * RK ++ ;
 GET_ULONG_LE ( X2 , input , 8 ) ;
 X2 ^= * RK ++ ;
 GET_ULONG_LE ( X3 , input , 12 ) ;
 X3 ^= * RK ++ ;
 if ( mode == AES_DECRYPT ) {
 for ( i = ( ctx -> nr >> 1 ) - 1 ;
 i > 0 ;
 i -- ) {
 AES_RROUND ( Y0 , Y1 , Y2 , Y3 , X0 , X1 , X2 , X3 ) ;
 AES_RROUND ( X0 , X1 , X2 , X3 , Y0 , Y1 , Y2 , Y3 ) ;
 }
 AES_RROUND ( Y0 , Y1 , Y2 , Y3 , X0 , X1 , X2 , X3 ) ;
 X0 = * RK ++ ^ ( RSb [ ( Y0 ) & 0xFF ] ) ^ ( RSb [ ( Y3 >> 8 ) & 0xFF ] << 8 ) ^ ( RSb [ ( Y2 >> 16 ) & 0xFF ] << 16 ) ^ ( ( ( unsigned int ) RSb [ ( Y1 >> 24 ) & 0xFF ] ) << 24 ) ;
 X1 = * RK ++ ^ ( RSb [ ( Y1 ) & 0xFF ] ) ^ ( RSb [ ( Y0 >> 8 ) & 0xFF ] << 8 ) ^ ( RSb [ ( Y3 >> 16 ) & 0xFF ] << 16 ) ^ ( ( ( unsigned int ) RSb [ ( Y2 >> 24 ) & 0xFF ] ) << 24 ) ;
 X2 = * RK ++ ^ ( RSb [ ( Y2 ) & 0xFF ] ) ^ ( RSb [ ( Y1 >> 8 ) & 0xFF ] << 8 ) ^ ( RSb [ ( Y0 >> 16 ) & 0xFF ] << 16 ) ^ ( ( ( unsigned int ) RSb [ ( Y3 >> 24 ) & 0xFF ] ) << 24 ) ;
 X3 = * RK ++ ^ ( RSb [ ( Y3 ) & 0xFF ] ) ^ ( RSb [ ( Y2 >> 8 ) & 0xFF ] << 8 ) ^ ( RSb [ ( Y1 >> 16 ) & 0xFF ] << 16 ) ^ ( ( ( unsigned int ) RSb [ ( Y0 >> 24 ) & 0xFF ] ) << 24 ) ;
 }
 else {
 for ( i = ( ctx -> nr >> 1 ) - 1 ;
 i > 0 ;
 i -- ) {
 AES_FROUND ( Y0 , Y1 , Y2 , Y3 , X0 , X1 , X2 , X3 ) ;
 AES_FROUND ( X0 , X1 , X2 , X3 , Y0 , Y1 , Y2 , Y3 ) ;
 }
 AES_FROUND ( Y0 , Y1 , Y2 , Y3 , X0 , X1 , X2 , X3 ) ;
 X0 = * RK ++ ^ ( FSb [ ( Y0 ) & 0xFF ] ) ^ ( FSb [ ( Y1 >> 8 ) & 0xFF ] << 8 ) ^ ( FSb [ ( Y2 >> 16 ) & 0xFF ] << 16 ) ^ ( ( ( unsigned int ) FSb [ ( Y3 >> 24 ) & 0xFF ] ) << 24 ) ;
 X1 = * RK ++ ^ ( FSb [ ( Y1 ) & 0xFF ] ) ^ ( FSb [ ( Y2 >> 8 ) & 0xFF ] << 8 ) ^ ( FSb [ ( Y3 >> 16 ) & 0xFF ] << 16 ) ^ ( ( ( unsigned int ) FSb [ ( Y0 >> 24 ) & 0xFF ] ) << 24 ) ;
 X2 = * RK ++ ^ ( FSb [ ( Y2 ) & 0xFF ] ) ^ ( FSb [ ( Y3 >> 8 ) & 0xFF ] << 8 ) ^ ( FSb [ ( Y0 >> 16 ) & 0xFF ] << 16 ) ^ ( ( ( unsigned int ) FSb [ ( Y1 >> 24 ) & 0xFF ] ) << 24 ) ;
 X3 = * RK ++ ^ ( FSb [ ( Y3 ) & 0xFF ] ) ^ ( FSb [ ( Y0 >> 8 ) & 0xFF ] << 8 ) ^ ( FSb [ ( Y1 >> 16 ) & 0xFF ] << 16 ) ^ ( ( ( unsigned int ) FSb [ ( Y2 >> 24 ) & 0xFF ] ) << 24 ) ;
 }
 PUT_ULONG_LE ( X0 , output , 0 ) ;
 PUT_ULONG_LE ( X1 , output , 4 ) ;
 PUT_ULONG_LE ( X2 , output , 8 ) ;
 PUT_ULONG_LE ( X3 , output , 12 ) ;
 }

