static VALUE ossl_cipher_init ( int argc , VALUE * argv , VALUE self , int mode ) {
 EVP_CIPHER_CTX * ctx ;
 unsigned char key [ EVP_MAX_KEY_LENGTH ] , * p_key = NULL ;
 unsigned char iv [ EVP_MAX_IV_LENGTH ] , * p_iv = NULL ;
 VALUE pass , init_v ;
 if ( rb_scan_args ( argc , argv , "02" , & pass , & init_v ) > 0 ) {
 VALUE cname = rb_class_path ( rb_obj_class ( self ) ) ;
 rb_warn ( "arguments for %" PRIsVALUE "#encrypt and %" PRIsVALUE "#decrypt were deprecated;
 " "use %" PRIsVALUE "#pkcs5_keyivgen to derive key and IV" , cname , cname , cname ) ;
 StringValue ( pass ) ;
 GetCipher ( self , ctx ) ;
 if ( NIL_P ( init_v ) ) memcpy ( iv , "OpenSSL for Ruby rulez!" , sizeof ( iv ) ) ;
 else {
 StringValue ( init_v ) ;
 if ( EVP_MAX_IV_LENGTH > RSTRING_LEN ( init_v ) ) {
 memset ( iv , 0 , EVP_MAX_IV_LENGTH ) ;
 memcpy ( iv , RSTRING_PTR ( init_v ) , RSTRING_LEN ( init_v ) ) ;
 }
 else memcpy ( iv , RSTRING_PTR ( init_v ) , sizeof ( iv ) ) ;
 }
 EVP_BytesToKey ( EVP_CIPHER_CTX_cipher ( ctx ) , EVP_md5 ( ) , iv , ( unsigned char * ) RSTRING_PTR ( pass ) , RSTRING_LENINT ( pass ) , 1 , key , NULL ) ;
 p_key = key ;
 p_iv = iv ;
 }
 else {
 GetCipher ( self , ctx ) ;
 }
 if ( EVP_CipherInit_ex ( ctx , NULL , NULL , p_key , p_iv , mode ) != 1 ) {
 ossl_raise ( eCipherError , NULL ) ;
 }
 return self ;
 }

static VALUE ossl_cipher_pkcs5_keyivgen ( int argc , VALUE * argv , VALUE self ) {
 EVP_CIPHER_CTX * ctx ;
 const EVP_MD * digest ;
 VALUE vpass , vsalt , viter , vdigest ;
 unsigned char key [ EVP_MAX_KEY_LENGTH ] , iv [ EVP_MAX_IV_LENGTH ] , * salt = NULL ;
 int iter ;
 rb_scan_args ( argc , argv , "13" , & vpass , & vsalt , & viter , & vdigest ) ;
 StringValue ( vpass ) ;
 if ( ! NIL_P ( vsalt ) ) {
 StringValue ( vsalt ) ;
 if ( RSTRING_LEN ( vsalt ) != PKCS5_SALT_LEN ) ossl_raise ( eCipherError , "salt must be an 8-octet string" ) ;
 salt = ( unsigned char * ) RSTRING_PTR ( vsalt ) ;
 }
 iter = NIL_P ( viter ) ? 2048 : NUM2INT ( viter ) ;
 digest = NIL_P ( vdigest ) ? EVP_md5 ( ) : GetDigestPtr ( vdigest ) ;
 GetCipher ( self , ctx ) ;
 EVP_BytesToKey ( EVP_CIPHER_CTX_cipher ( ctx ) , digest , salt , ( unsigned char * ) RSTRING_PTR ( vpass ) , RSTRING_LENINT ( vpass ) , iter , key , iv ) ;
 if ( EVP_CipherInit_ex ( ctx , NULL , NULL , key , iv , - 1 ) != 1 ) ossl_raise ( eCipherError , NULL ) ;
 OPENSSL_cleanse ( key , sizeof key ) ;
 OPENSSL_cleanse ( iv , sizeof iv ) ;
 return Qnil ;
 }

static VALUE ossl_cipher_update ( int argc , VALUE * argv , VALUE self ) {
 EVP_CIPHER_CTX * ctx ;
 unsigned char * in ;
 long in_len , out_len ;
 VALUE data , str ;
 rb_scan_args ( argc , argv , "11" , & data , & str ) ;
 StringValue ( data ) ;
 in = ( unsigned char * ) RSTRING_PTR ( data ) ;
 if ( ( in_len = RSTRING_LEN ( data ) ) == 0 ) ossl_raise ( rb_eArgError , "data must not be empty" ) ;
 GetCipher ( self , ctx ) ;
 out_len = in_len + EVP_CIPHER_CTX_block_size ( ctx ) ;
 if ( out_len <= 0 ) {
 ossl_raise ( rb_eRangeError , "data too big to make output buffer: %ld bytes" , in_len ) ;
 }
 if ( NIL_P ( str ) ) {
 str = rb_str_new ( 0 , out_len ) ;
 }
 else {
 StringValue ( str ) ;
 rb_str_resize ( str , out_len ) ;
 }
 if ( ! ossl_cipher_update_long ( ctx , ( unsigned char * ) RSTRING_PTR ( str ) , & out_len , in , in_len ) ) ossl_raise ( eCipherError , NULL ) ;
 assert ( out_len < RSTRING_LEN ( str ) ) ;
 rb_str_set_len ( str , out_len ) ;
 return str ;
 }

