 }

static int read_intra_segment_id ( VP9_COMMON * const cm , MACROBLOCKD * const xd , int mi_row , int mi_col , vp9_reader * r ) {
 struct segmentation * const seg = & cm -> seg ;
 const BLOCK_SIZE bsize = xd -> mi [ 0 ] -> mbmi . sb_type ;
 int segment_id ;
 if ( ! seg -> enabled ) return 0 ;
 if ( ! seg -> update_map ) return 0 ;
 segment_id = read_segment_id ( r , seg ) ;
 set_segment_id ( cm , bsize , mi_row , mi_col , segment_id ) ;
 return segment_id ;
 }

static int read_inter_segment_id ( VP9_COMMON * const cm , MACROBLOCKD * const xd , int mi_row , int mi_col , vp9_reader * r ) {
 struct segmentation * const seg = & cm -> seg ;
 MB_MODE_INFO * const mbmi = & xd -> mi [ 0 ] -> mbmi ;
 const BLOCK_SIZE bsize = mbmi -> sb_type ;
 int predicted_segment_id , segment_id ;
 if ( ! seg -> enabled ) return 0 ;
 predicted_segment_id = vp9_get_segment_id ( cm , cm -> last_frame_seg_map , bsize , mi_row , mi_col ) ;
 if ( ! seg -> update_map ) return predicted_segment_id ;
 if ( seg -> temporal_update ) {
 const vp9_prob pred_prob = vp9_get_pred_prob_seg_id ( seg , xd ) ;
 mbmi -> seg_id_predicted = vp9_read ( r , pred_prob ) ;
 segment_id = mbmi -> seg_id_predicted ? predicted_segment_id : read_segment_id ( r , seg ) ;
 }
 else {
 segment_id = read_segment_id ( r , seg ) ;
 }
 set_segment_id ( cm , bsize , mi_row , mi_col , segment_id ) ;
 return segment_id ;
 }

static void build_inter_predictors ( MACROBLOCKD * xd , int plane , int block , int bw , int bh , int x , int y , int w , int h , int mi_x , int mi_y ) {
 struct macroblockd_plane * const pd = & xd -> plane [ plane ] ;
 const MODE_INFO * mi = xd -> mi [ 0 ] ;
 const int is_compound = has_second_ref ( & mi -> mbmi ) ;
 const InterpKernel * kernel = vp9_get_interp_kernel ( mi -> mbmi . interp_filter ) ;
 int ref ;
 for ( ref = 0 ;
 ref < 1 + is_compound ;
 ++ ref ) {
 const struct scale_factors * const sf = & xd -> block_refs [ ref ] -> sf ;
 struct buf_2d * const pre_buf = & pd -> pre [ ref ] ;
 struct buf_2d * const dst_buf = & pd -> dst ;
 uint8_t * const dst = dst_buf -> buf + dst_buf -> stride * y + x ;
 const MV mv = mi -> mbmi . sb_type < BLOCK_8X8 ? average_split_mvs ( pd , mi , ref , block ) : mi -> mbmi . mv [ ref ] . as_mv ;
 const MV mv_q4 = clamp_mv_to_umv_border_sb ( xd , & mv , bw , bh , pd -> subsampling_x , pd -> subsampling_y ) ;
 uint8_t * pre ;
 MV32 scaled_mv ;
 int xs , ys , subpel_x , subpel_y ;
 if ( vp9_is_scaled ( sf ) ) {
 pre = pre_buf -> buf + scaled_buffer_offset ( x , y , pre_buf -> stride , sf ) ;
 scaled_mv = vp9_scale_mv ( & mv_q4 , mi_x + x , mi_y + y , sf ) ;
 xs = sf -> x_step_q4 ;
 ys = sf -> y_step_q4 ;
 }
 else {
 pre = pre_buf -> buf + ( y * pre_buf -> stride + x ) ;
 scaled_mv . row = mv_q4 . row ;
 scaled_mv . col = mv_q4 . col ;
 xs = ys = 16 ;
 }
 subpel_x = scaled_mv . col & SUBPEL_MASK ;
 subpel_y = scaled_mv . row & SUBPEL_MASK ;
 pre += ( scaled_mv . row >> SUBPEL_BITS ) * pre_buf -> stride + ( scaled_mv . col >> SUBPEL_BITS ) ;
 inter_predictor ( pre , pre_buf -> stride , dst , dst_buf -> stride , subpel_x , subpel_y , sf , w , h , ref , kernel , xs , ys ) ;
 }
 }

void vp9_dec_build_inter_predictors_sb ( MACROBLOCKD * xd , int mi_row , int mi_col , BLOCK_SIZE bsize ) {
 int plane ;
 const int mi_x = mi_col * MI_SIZE ;
 const int mi_y = mi_row * MI_SIZE ;
 for ( plane = 0 ;
 plane < MAX_MB_PLANE ;
 ++ plane ) {
 const BLOCK_SIZE plane_bsize = get_plane_block_size ( bsize , & xd -> plane [ plane ] ) ;
 const int num_4x4_w = num_4x4_blocks_wide_lookup [ plane_bsize ] ;
 const int num_4x4_h = num_4x4_blocks_high_lookup [ plane_bsize ] ;
 const int bw = 4 * num_4x4_w ;
 const int bh = 4 * num_4x4_h ;
 if ( xd -> mi [ 0 ] -> mbmi . sb_type < BLOCK_8X8 ) {
 int i = 0 , x , y ;
 assert ( bsize == BLOCK_8X8 ) ;
 for ( y = 0 ;
 y < num_4x4_h ;
 ++ y ) for ( x = 0 ;
 x < num_4x4_w ;
 ++ x ) dec_build_inter_predictors ( xd , plane , i ++ , bw , bh , * x , 4 * y , 4 , 4 , mi_x , mi_y ) ;
 }
 else {
 dec_build_inter_predictors ( xd , plane , 0 , bw , bh , 0 , 0 , bw , bh , mi_x , mi_y ) ;
 }
 }
 }

