void vp8_strict_quantize_b_c ( BLOCK * b , BLOCKD * d ) {
 int i ;
 int rc ;
 int eob ;
 int x ;
 int y ;
 int z ;
 int sz ;
 short * coeff_ptr ;
 short * quant_ptr ;
 short * quant_shift_ptr ;
 short * qcoeff_ptr ;
 short * dqcoeff_ptr ;
 short * dequant_ptr ;
 coeff_ptr = b -> coeff ;
 quant_ptr = b -> quant ;
 quant_shift_ptr = b -> quant_shift ;
 qcoeff_ptr = d -> qcoeff ;
 dqcoeff_ptr = d -> dqcoeff ;
 dequant_ptr = d -> dequant ;
 eob = - 1 ;
 vpx_memset ( qcoeff_ptr , 0 , 32 ) ;
 vpx_memset ( dqcoeff_ptr , 0 , 32 ) ;
 for ( i = 0 ;
 i < 16 ;
 i ++ ) {
 int dq ;
 int rounding ;
 rc = vp8_default_zig_zag1d [ i ] ;
 z = coeff_ptr [ rc ] ;
 dq = dequant_ptr [ rc ] ;
 rounding = dq >> 1 ;
 sz = - ( z < 0 ) ;
 x = ( z + sz ) ^ sz ;
 x += rounding ;
 if ( x >= dq ) {
 y = ( ( ( ( x * quant_ptr [ rc ] ) >> 16 ) + x ) * quant_shift_ptr [ rc ] ) >> 16 ;
 x = ( y + sz ) ^ sz ;
 qcoeff_ptr [ rc ] = x ;
 dqcoeff_ptr [ rc ] = x * dq ;
 if ( y ) eob = i ;
 }
 }
 * d -> eob = ( char ) ( eob + 1 ) ;
 }

static int compute_rd_thresh_factor ( int qindex ) {
 const int q = ( int ) ( pow ( vp9_dc_quant ( qindex , 0 ) / 4.0 , RD_THRESH_POW ) * 5.12 ) ;
 return MAX ( q , 8 ) ;
 }

int vp9_compute_rd_mult ( const VP9_COMP * cpi , int qindex ) {
 const int q = vp9_dc_quant ( qindex , 0 ) ;
 int rdmult = 88 * q * q / 24 ;
 if ( cpi -> oxcf . pass == 2 && ( cpi -> common . frame_type != KEY_FRAME ) ) {
 const GF_GROUP * const gf_group = & cpi -> twopass . gf_group ;
 const FRAME_UPDATE_TYPE frame_type = gf_group -> update_type [ gf_group -> index ] ;
 const int boost_index = MIN ( 15 , ( cpi -> rc . gfu_boost / 100 ) ) ;
 rdmult = ( rdmult * rd_frame_type_factor [ frame_type ] ) >> 7 ;
 rdmult += ( ( rdmult * rd_boost_factor [ boost_index ] ) >> 7 ) ;
 }
 return rdmult ;
 }

static void set_block_thresholds ( const VP9_COMMON * cm , RD_OPT * rd ) {
 int i , bsize , segment_id ;
 for ( segment_id = 0 ;
 segment_id < MAX_SEGMENTS ;
 ++ segment_id ) {
 const int qindex = clamp ( vp9_get_qindex ( & cm -> seg , segment_id , cm -> base_qindex ) + cm -> y_dc_delta_q , 0 , MAXQ ) ;
 const int q = compute_rd_thresh_factor ( qindex ) ;
 for ( bsize = 0 ;
 bsize < BLOCK_SIZES ;
 ++ bsize ) {
 const int t = q * rd_thresh_block_size_factor [ bsize ] ;
 const int thresh_max = INT_MAX / t ;
 if ( bsize >= BLOCK_8X8 ) {
 for ( i = 0 ;
 i < MAX_MODES ;
 ++ i ) rd -> threshes [ segment_id ] [ bsize ] [ i ] = rd -> thresh_mult [ i ] < thresh_max ? rd -> thresh_mult [ i ] * t / 4 : INT_MAX ;
 }
 else {
 for ( i = 0 ;
 i < MAX_REFS ;
 ++ i ) rd -> threshes [ segment_id ] [ bsize ] [ i ] = rd -> thresh_mult_sub8x8 [ i ] < thresh_max ? rd -> thresh_mult_sub8x8 [ i ] * t / 4 : INT_MAX ;
 }
 }
 }
 }

