 IF_DIFF_REF_FRAME_ADD_MV ( candidate ) ;
 }
 }
 }
 if ( prev_mbmi ) IF_DIFF_REF_FRAME_ADD_MV ( prev_mbmi ) ;
 Done : mi -> mbmi . mode_context [ ref_frame ] = counter_to_context [ context_counter ] ;
 for ( i = 0 ;
