 else if ( arg_match ( & arg , & min_bitrate_arg , argi ) ) {
 min_bitrate = arg_parse_uint ( & arg ) ;
 }
 else if ( arg_match ( & arg , & max_bitrate_arg , argi ) ) {
 max_bitrate = arg_parse_uint ( & arg ) ;
 }
 else {
 ++ argj ;
 }
 }
