 j < 8 ;
 ++ j ) decay_accumulator *= recent_loop_decay [ j ] ;
 if ( detect_transition_to_still ( twopass , i , cpi -> oxcf . key_freq - i , loop_decay_rate , decay_accumulator ) ) break ;
 ++ rc -> frames_to_key ;
 if ( rc -> frames_to_key >= 2 * cpi -> oxcf . key_freq ) break ;
 }
 else {
 ++ rc -> frames_to_key ;
 }
 ++ i ;
 }
