 gf_group -> update_type [ 0 ] = KF_UPDATE ;
 gf_group -> rf_level [ 0 ] = KF_STD ;
 twopass -> kf_group_error_left = ( int ) ( kf_group_err - kf_mod_err ) ;
 twopass -> modified_error_left -= kf_group_err ;
