 int sum = 0 ;
 for ( i = - 8 ;
 i < 0 ;
 i ++ ) s [ i ] = s [ 0 ] ;
 for ( i = cols ;
 i < cols + 17 ;
 i ++ ) s [ i ] = s [ cols - 1 ] ;
 for ( i = - 8 ;
 i <= 6 ;
 i ++ ) {
 sumsq += s [ i ] * s [ i ] ;
 sum += s [ i ] ;
 d [ i + 8 ] = 0 ;
 }
 for ( c = 0 ;
 c < cols + 8 ;
 c ++ ) {
 int x = s [ c + 7 ] - s [ c - 8 ] ;
 int y = s [ c + 7 ] + s [ c - 8 ] ;
 sum += x ;
 sumsq += x * y ;
 d [ c & 15 ] = s [ c ] ;
