 for ( i = - 8 ;
 i < 0 ;
 i ++ ) s [ i * pitch ] = s [ 0 ] ;
 for ( i = rows ;
 i < rows + 17 ;
 i ++ ) s [ i * pitch ] = s [ ( rows - 1 ) * pitch ] ;
 for ( i = - 8 ;
 i <= 6 ;
 i ++ ) {
 sumsq += s [ i * pitch ] * s [ i * pitch ] ;
 sum += s [ i * pitch ] ;
 }
 for ( r = 0 ;
 r < rows + 8 ;
 r ++ ) {
 sumsq += s [ 7 * pitch ] * s [ 7 * pitch ] - s [ - 8 * pitch ] * s [ - 8 * pitch ] ;
 sum += s [ 7 * pitch ] - s [ - 8 * pitch ] ;
