 vpx_memset ( cpi -> segmentation_map , 0 , cm -> mi_rows * cm -> mi_cols ) ;
 seg -> update_map = 0 ;
 seg -> update_data = 0 ;
 cpi -> static_mb_pct = 0 ;
 vp9_disable_segmentation ( seg ) ;
 vp9_clearall_segfeatures ( seg ) ;
 vp9_update_mbgraph_stats ( cpi ) ;
 if ( seg -> enabled ) {
 seg -> update_map = 1 ;
 seg -> update_data = 1 ;
