 RANGE_CHECK_HI ( cfg , rc_resize_down_thresh , 100 ) ;
 RANGE_CHECK ( cfg , g_pass , VPX_RC_ONE_PASS , VPX_RC_LAST_PASS ) ;
 if ( cfg -> rc_resize_allowed == 1 ) {
