 layer_id = ( int ) stats -> spatial_layer_id ;
 if ( layer_id >= cfg -> ss_number_layers || ( unsigned int ) ( stats -> count + 0.5 ) != n_packets_per_layer [ layer_id ] - 1 ) ERROR ( "rc_twopass_stats_in missing EOS stats packet" ) ;
