 }
 qcoeff [ rc ] = x ;
 dqcoeff [ rc ] = ( x * dequant_ptr [ rc != 0 ] ) / mul ;
 next = tokens [ i ] [ best ] . next ;
 best = best_index [ i ] [ best ] ;
 }
