 }
 for ( i = 11 ;
 ( int ) i < 11 + mode_to_num_layers [ layering_mode ] ;
 ++ i ) {
 cfg . ts_target_bitrate [ i - 11 ] = strtol ( argv [ i ] , NULL , 0 ) ;
 }
 cfg . rc_dropframe_thresh = strtol ( argv [ 9 ] , NULL , 0 ) ;
 cfg . rc_end_usage = VPX_CBR ;
 cfg . rc_resize_allowed = 0 ;
