 frame_avail = vpx_img_read ( & raw , infile ) ;
 if ( frame_avail ) ++ rc . layer_input_frames [ layer_id . temporal_layer_id ] ;
 vpx_usec_timer_start ( & timer ) ;
 if ( vpx_codec_encode ( & codec , frame_avail ? & raw : NULL , pts , 1 , flags , VPX_DL_REALTIME ) ) {
