int get_vp9_frame_buffer ( void * cb_priv , size_t min_size , vpx_codec_frame_buffer_t * fb ) {
 int i ;
 struct ExternalFrameBufferList * const ext_fb_list = ( struct ExternalFrameBufferList * ) cb_priv ;
 if ( ext_fb_list == NULL ) return - 1 ;
 for ( i = 0 ;
 i < ext_fb_list -> num_external_frame_buffers ;
 ++ i ) {
 if ( ! ext_fb_list -> ext_fb [ i ] . in_use ) break ;
 }
 if ( i == ext_fb_list -> num_external_frame_buffers ) return - 1 ;
 if ( ext_fb_list -> ext_fb [ i ] . size < min_size ) {
 free ( ext_fb_list -> ext_fb [ i ] . data ) ;
 ext_fb_list -> ext_fb [ i ] . data = ( uint8_t * ) malloc ( min_size ) ;
 if ( ! ext_fb_list -> ext_fb [ i ] . data ) return - 1 ;
 ext_fb_list -> ext_fb [ i ] . size = min_size ;
 }
 fb -> data = ext_fb_list -> ext_fb [ i ] . data ;
 fb -> size = ext_fb_list -> ext_fb [ i ] . size ;
 ext_fb_list -> ext_fb [ i ] . in_use = 1 ;
 fb -> priv = & ext_fb_list -> ext_fb [ i ] ;
 return 0 ;
 }

static void fd_list_add ( struct FrameData * * list , struct FrameData * layer_data ) {
 struct FrameData * * p = list ;
 while ( * p != NULL ) p = & ( * p ) -> next ;
 * p = layer_data ;
 layer_data -> next = NULL ;
 }

void vpx_svc_set_keyframe ( SvcContext * svc_ctx ) {
 SvcInternal * const si = get_svc_internal ( svc_ctx ) ;
 if ( svc_ctx == NULL || si == NULL ) return ;
 si -> frame_within_gop = 0 ;
 }

vpx_codec_err_t vpx_svc_get_layer_resolution ( const SvcContext * svc_ctx , int layer , unsigned int * width , unsigned int * height ) {
 int w , h , index , num , den ;
 const SvcInternal * const si = get_const_svc_internal ( svc_ctx ) ;
 if ( svc_ctx == NULL || si == NULL || width == NULL || height == NULL ) {
 return VPX_CODEC_INVALID_PARAM ;
 }
 if ( layer < 0 || layer >= si -> layers ) return VPX_CODEC_INVALID_PARAM ;
 index = layer + VPX_SS_MAX_LAYERS - si -> layers ;
 num = si -> scaling_factor_num [ index ] ;
 den = si -> scaling_factor_den [ index ] ;
 if ( num == 0 || den == 0 ) return VPX_CODEC_INVALID_PARAM ;
 w = si -> width * num / den ;
 h = si -> height * num / den ;
 w += w % 2 ;
 h += h % 2 ;
 * width = w ;
 * height = h ;
 return VPX_CODEC_OK ;
 }

static struct FrameData * fd_create ( void * buf , size_t size , vpx_codec_frame_flags_t flags ) {
 struct FrameData * const frame_data = ( struct FrameData * ) vpx_malloc ( sizeof ( * frame_data ) ) ;
 if ( frame_data == NULL ) {
 return NULL ;
 }
 frame_data -> buf = vpx_malloc ( size ) ;
 if ( frame_data -> buf == NULL ) {
 vpx_free ( frame_data ) ;
 return NULL ;
 }
 vpx_memcpy ( frame_data -> buf , buf , size ) ;
 frame_data -> size = size ;
 frame_data -> flags = flags ;
 return frame_data ;
 }

static vpx_codec_err_t parse_quantizer_values ( SvcContext * svc_ctx , const char * quantizer_values ) {
 char * input_string ;
 char * token ;
 const char * delim = "," ;
 char * save_ptr ;
 int found = 0 ;
 int i , q ;
 vpx_codec_err_t res = VPX_CODEC_OK ;
 SvcInternal * const si = get_svc_internal ( svc_ctx ) ;
 if ( quantizer_values == NULL || strlen ( quantizer_values ) == 0 ) {
 input_string = strdup ( DEFAULT_QUANTIZER_VALUES ) ;
 }
 else {
 input_string = strdup ( quantizer_values ) ;
 }
 token = strtok_r ( input_string , delim , & save_ptr ) ;
 for ( i = 0 ;
 i < svc_ctx -> spatial_layers ;
 ++ i ) {
 if ( token != NULL ) {
 q = atoi ( token ) ;
 if ( q <= 0 || q > 100 ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "svc-quantizer-values: invalid value %s\n" , token ) ;
 res = VPX_CODEC_INVALID_PARAM ;
 break ;
 }
 token = strtok_r ( NULL , delim , & save_ptr ) ;
 found = i + 1 ;
 }
 else {
 q = 0 ;
 }
 si -> quantizer [ i + VPX_SS_MAX_LAYERS - svc_ctx -> spatial_layers ] = q ;
 }
 if ( res == VPX_CODEC_OK && found != svc_ctx -> spatial_layers ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "svc: quantizers: %d values required, but only %d specified\n" , svc_ctx -> spatial_layers , found ) ;
 res = VPX_CODEC_INVALID_PARAM ;
 }
 free ( input_string ) ;
 return res ;
 }

