static void log_invalid_scale_factor ( SvcContext * svc_ctx , const char * value ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "svc scale-factors: invalid value %s\n" , value ) ;
 }

static void set_svc_parameters ( SvcContext * svc_ctx , vpx_codec_ctx_t * codec_ctx ) {
 int layer , layer_index ;
 vpx_svc_parameters_t svc_params ;
 SvcInternal * const si = get_svc_internal ( svc_ctx ) ;
 memset ( & svc_params , 0 , sizeof ( svc_params ) ) ;
 svc_params . temporal_layer = 0 ;
 svc_params . spatial_layer = si -> layer ;
 layer = si -> layer ;
 if ( VPX_CODEC_OK != vpx_svc_get_layer_resolution ( svc_ctx , layer , & svc_params . width , & svc_params . height ) ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "vpx_svc_get_layer_resolution failed\n" ) ;
 }
 layer_index = layer + VPX_SS_MAX_LAYERS - si -> layers ;
 if ( codec_ctx -> config . enc -> g_pass == VPX_RC_ONE_PASS ) {
 svc_params . min_quantizer = si -> quantizer [ layer_index ] ;
 svc_params . max_quantizer = si -> quantizer [ layer_index ] ;
 }
 else {
 svc_params . min_quantizer = codec_ctx -> config . enc -> rc_min_quantizer ;
 svc_params . max_quantizer = codec_ctx -> config . enc -> rc_max_quantizer ;
 }
 svc_params . distance_from_i_frame = si -> frame_within_gop ;
 vpx_codec_control ( codec_ctx , VP9E_SET_SVC_PARAMETERS , & svc_params ) ;
 }

static vpx_codec_err_t parse_scale_factors ( SvcContext * svc_ctx , const char * scale_factors ) {
 char * input_string ;
 char * token ;
 const char * delim = "," ;
 char * save_ptr ;
 int found = 0 ;
 int i ;
 int64_t num , den ;
 vpx_codec_err_t res = VPX_CODEC_OK ;
 SvcInternal * const si = get_svc_internal ( svc_ctx ) ;
 if ( scale_factors == NULL || strlen ( scale_factors ) == 0 ) {
 input_string = strdup ( DEFAULT_SCALE_FACTORS ) ;
 }
 else {
 input_string = strdup ( scale_factors ) ;
 }
 token = strtok_r ( input_string , delim , & save_ptr ) ;
 for ( i = 0 ;
 i < svc_ctx -> spatial_layers ;
 ++ i ) {
 num = den = 0 ;
 if ( token != NULL ) {
 num = strtol ( token , & token , 10 ) ;
 if ( num <= 0 ) {
 log_invalid_scale_factor ( svc_ctx , token ) ;
 res = VPX_CODEC_INVALID_PARAM ;
 break ;
 }
 if ( * token ++ != '/' ) {
 log_invalid_scale_factor ( svc_ctx , token ) ;
 res = VPX_CODEC_INVALID_PARAM ;
 break ;
 }
 den = strtol ( token , & token , 10 ) ;
 if ( den <= 0 ) {
 log_invalid_scale_factor ( svc_ctx , token ) ;
 res = VPX_CODEC_INVALID_PARAM ;
 break ;
 }
 token = strtok_r ( NULL , delim , & save_ptr ) ;
 found = i + 1 ;
 }
 si -> scaling_factor_num [ i + VPX_SS_MAX_LAYERS - svc_ctx -> spatial_layers ] = ( int ) num ;
 si -> scaling_factor_den [ i + VPX_SS_MAX_LAYERS - svc_ctx -> spatial_layers ] = ( int ) den ;
 }
 if ( res == VPX_CODEC_OK && found != svc_ctx -> spatial_layers ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "svc: scale-factors: %d values required, but only %d specified\n" , svc_ctx -> spatial_layers , found ) ;
 res = VPX_CODEC_INVALID_PARAM ;
 }
 free ( input_string ) ;
 return res ;
 }

void vpx_svc_release ( SvcContext * svc_ctx ) {
 SvcInternal * si ;
 if ( svc_ctx == NULL ) return ;
 si = ( SvcInternal * ) svc_ctx -> internal ;
 if ( si != NULL ) {
 fd_free ( si -> frame_temp ) ;
 fd_free_list ( si -> frame_list ) ;
 if ( si -> rc_stats_buf ) {
 free ( si -> rc_stats_buf ) ;
 }
 free ( si ) ;
 svc_ctx -> internal = NULL ;
 }
 }

const char * vpx_svc_dump_statistics ( SvcContext * svc_ctx ) {
 int number_of_frames , encode_frame_count ;
 int i , j ;
 uint32_t bytes_total = 0 ;
 double scale [ COMPONENTS ] ;
 double psnr [ COMPONENTS ] ;
 double mse [ COMPONENTS ] ;
 double y_scale ;
 SvcInternal * const si = get_svc_internal ( svc_ctx ) ;
 if ( svc_ctx == NULL || si == NULL ) return NULL ;
 svc_log_reset ( svc_ctx ) ;
 encode_frame_count = si -> encode_frame_count ;
 if ( si -> encode_frame_count <= 0 ) return vpx_svc_get_message ( svc_ctx ) ;
 svc_log ( svc_ctx , SVC_LOG_INFO , "\n" ) ;
 for ( i = 0 ;
 i < si -> layers ;
 ++ i ) {
 number_of_frames = encode_frame_count ;
 svc_log ( svc_ctx , SVC_LOG_INFO , "Layer %d Average PSNR=[%2.3f, %2.3f, %2.3f, %2.3f], Bytes=[%u]\n" , i , ( double ) si -> psnr_sum [ i ] [ 0 ] / number_of_frames , ( double ) si -> psnr_sum [ i ] [ 1 ] / number_of_frames , ( double ) si -> psnr_sum [ i ] [ 2 ] / number_of_frames , ( double ) si -> psnr_sum [ i ] [ 3 ] / number_of_frames , si -> bytes_sum [ i ] ) ;
 y_scale = si -> width * si -> height * 255.0 * 255.0 * number_of_frames ;
 scale [ 1 ] = y_scale ;
 scale [ 2 ] = scale [ 3 ] = y_scale / 4 ;
 scale [ 0 ] = y_scale * 1.5 ;
 for ( j = 0 ;
 j < COMPONENTS ;
 j ++ ) {
 psnr [ j ] = calc_psnr ( si -> sse_sum [ i ] [ j ] / scale [ j ] ) ;
 mse [ j ] = si -> sse_sum [ i ] [ j ] * 255.0 * 255.0 / scale [ j ] ;
 }
 svc_log ( svc_ctx , SVC_LOG_INFO , "Layer %d Overall PSNR=[%2.3f, %2.3f, %2.3f, %2.3f]\n" , i , psnr [ 0 ] , psnr [ 1 ] , psnr [ 2 ] , psnr [ 3 ] ) ;
 svc_log ( svc_ctx , SVC_LOG_INFO , "Layer %d Overall MSE=[%2.3f, %2.3f, %2.3f, %2.3f]\n" , i , mse [ 0 ] , mse [ 1 ] , mse [ 2 ] , mse [ 3 ] ) ;
 bytes_total += si -> bytes_sum [ i ] ;
 si -> bytes_sum [ i ] = 0 ;
 for ( j = 0 ;
 j < COMPONENTS ;
 ++ j ) {
 si -> psnr_sum [ i ] [ j ] = 0 ;
 si -> sse_sum [ i ] [ j ] = 0 ;
 }
 }
 si -> encode_frame_count = 0 ;
 svc_log ( svc_ctx , SVC_LOG_INFO , "Total Bytes=[%u]\n" , bytes_total ) ;
 return vpx_svc_get_message ( svc_ctx ) ;
 }

vpx_codec_err_t vpx_svc_encode ( SvcContext * svc_ctx , vpx_codec_ctx_t * codec_ctx , struct vpx_image * rawimg , vpx_codec_pts_t pts , int64_t duration , int deadline ) {
 vpx_codec_err_t res ;
 vpx_codec_iter_t iter ;
 const vpx_codec_cx_pkt_t * cx_pkt ;
 int layer_for_psnr = 0 ;
 SvcInternal * const si = get_svc_internal ( svc_ctx ) ;
 if ( svc_ctx == NULL || codec_ctx == NULL || si == NULL ) {
 return VPX_CODEC_INVALID_PARAM ;
 }
 svc_log_reset ( svc_ctx ) ;
 si -> rc_stats_buf_used = 0 ;
 si -> layers = svc_ctx -> spatial_layers ;
 if ( si -> encode_frame_count == 0 ) {
 si -> frame_within_gop = 0 ;
 }
 si -> is_keyframe = ( si -> frame_within_gop == 0 ) ;
 if ( rawimg != NULL ) {
 svc_log ( svc_ctx , SVC_LOG_DEBUG , "vpx_svc_encode layers: %d, frame_count: %d, " "frame_within_gop: %d\n" , si -> layers , si -> encode_frame_count , si -> frame_within_gop ) ;
 }
 if ( rawimg != NULL ) {
 for ( si -> layer = 0 ;
 si -> layer < si -> layers ;
 ++ si -> layer ) {
 set_svc_parameters ( svc_ctx , codec_ctx ) ;
 }
 }
 res = vpx_codec_encode ( codec_ctx , rawimg , pts , ( uint32_t ) duration , 0 , deadline ) ;
 if ( res != VPX_CODEC_OK ) {
 return res ;
 }
 iter = NULL ;
 while ( ( cx_pkt = vpx_codec_get_cx_data ( codec_ctx , & iter ) ) ) {
 switch ( cx_pkt -> kind ) {
 case VPX_CODEC_CX_FRAME_PKT : {
 fd_list_add ( & si -> frame_list , fd_create ( cx_pkt -> data . frame . buf , cx_pkt -> data . frame . sz , cx_pkt -> data . frame . flags ) ) ;
 svc_log ( svc_ctx , SVC_LOG_DEBUG , "SVC frame: %d, kf: %d, size: %d, " "pts: %d\n" , si -> frame_received , ( cx_pkt -> data . frame . flags & VPX_FRAME_IS_KEY ) ? 1 : 0 , ( int ) cx_pkt -> data . frame . sz , ( int ) cx_pkt -> data . frame . pts ) ;
 ++ si -> frame_received ;
 layer_for_psnr = 0 ;
 break ;
 }
 case VPX_CODEC_PSNR_PKT : {
 int i ;
 svc_log ( svc_ctx , SVC_LOG_DEBUG , "SVC frame: %d, layer: %d, PSNR(Total/Y/U/V): " "%2.3f %2.3f %2.3f %2.3f \n" , si -> frame_received , layer_for_psnr , cx_pkt -> data . psnr . psnr [ 0 ] , cx_pkt -> data . psnr . psnr [ 1 ] , cx_pkt -> data . psnr . psnr [ 2 ] , cx_pkt -> data . psnr . psnr [ 3 ] ) ;
 svc_log ( svc_ctx , SVC_LOG_DEBUG , "SVC frame: %d, layer: %d, SSE(Total/Y/U/V): " "%2.3f %2.3f %2.3f %2.3f \n" , si -> frame_received , layer_for_psnr , cx_pkt -> data . psnr . sse [ 0 ] , cx_pkt -> data . psnr . sse [ 1 ] , cx_pkt -> data . psnr . sse [ 2 ] , cx_pkt -> data . psnr . sse [ 3 ] ) ;
 for ( i = 0 ;
 i < COMPONENTS ;
 i ++ ) {
 si -> psnr_sum [ layer_for_psnr ] [ i ] += cx_pkt -> data . psnr . psnr [ i ] ;
 si -> sse_sum [ layer_for_psnr ] [ i ] += cx_pkt -> data . psnr . sse [ i ] ;
 }
 ++ layer_for_psnr ;
 break ;
 }
 case VPX_CODEC_STATS_PKT : {
 size_t new_size = si -> rc_stats_buf_used + cx_pkt -> data . twopass_stats . sz ;
 if ( new_size > si -> rc_stats_buf_size ) {
 char * p = ( char * ) realloc ( si -> rc_stats_buf , new_size ) ;
 if ( p == NULL ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "Error allocating stats buf\n" ) ;
 return VPX_CODEC_MEM_ERROR ;
 }
 si -> rc_stats_buf = p ;
 si -> rc_stats_buf_size = new_size ;
 }
 memcpy ( si -> rc_stats_buf + si -> rc_stats_buf_used , cx_pkt -> data . twopass_stats . buf , cx_pkt -> data . twopass_stats . sz ) ;
 si -> rc_stats_buf_used += cx_pkt -> data . twopass_stats . sz ;
 break ;
 }
 # if CONFIG_SPATIAL_SVC case VPX_CODEC_SPATIAL_SVC_LAYER_SIZES : {
 int i ;
 for ( i = 0 ;
 i < si -> layers ;
 ++ i ) si -> bytes_sum [ i ] += cx_pkt -> data . layer_sizes [ i ] ;
 break ;
 }
 # endif default : {
 break ;
 }
 }
 }
 if ( rawimg != NULL ) {
 ++ si -> frame_within_gop ;
 ++ si -> encode_frame_count ;
 }
 return VPX_CODEC_OK ;
 }

static vpx_codec_err_t parse_options ( SvcContext * svc_ctx , const char * options ) {
 char * input_string ;
 char * option_name ;
 char * option_value ;
 char * input_ptr ;
 SvcInternal * const si = get_svc_internal ( svc_ctx ) ;
 vpx_codec_err_t res = VPX_CODEC_OK ;
 if ( options == NULL ) return VPX_CODEC_OK ;
 input_string = strdup ( options ) ;
 option_name = strtok_r ( input_string , "=" , & input_ptr ) ;
 while ( option_name != NULL ) {
 option_value = strtok_r ( NULL , " " , & input_ptr ) ;
 if ( option_value == NULL ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "option missing value: %s\n" , option_name ) ;
 res = VPX_CODEC_INVALID_PARAM ;
 break ;
 }
 if ( strcmp ( "spatial-layers" , option_name ) == 0 ) {
 svc_ctx -> spatial_layers = atoi ( option_value ) ;
 }
 else if ( strcmp ( "temporal-layers" , option_name ) == 0 ) {
 svc_ctx -> temporal_layers = atoi ( option_value ) ;
 }
 else if ( strcmp ( "scale-factors" , option_name ) == 0 ) {
 res = parse_scale_factors ( svc_ctx , option_value ) ;
 if ( res != VPX_CODEC_OK ) break ;
 }
 else if ( strcmp ( "quantizers" , option_name ) == 0 ) {
 res = parse_quantizer_values ( svc_ctx , option_value ) ;
 if ( res != VPX_CODEC_OK ) break ;
 }
 else if ( strcmp ( "auto-alt-refs" , option_name ) == 0 ) {
 res = parse_auto_alt_ref ( svc_ctx , option_value ) ;
 if ( res != VPX_CODEC_OK ) break ;
 }
 else if ( strcmp ( "multi-frame-contexts" , option_name ) == 0 ) {
 si -> use_multiple_frame_contexts = atoi ( option_value ) ;
 }
 else {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "invalid option: %s\n" , option_name ) ;
 res = VPX_CODEC_INVALID_PARAM ;
 break ;
 }
 option_name = strtok_r ( NULL , "=" , & input_ptr ) ;
 }
 free ( input_string ) ;
 if ( si -> use_multiple_frame_contexts && ( svc_ctx -> spatial_layers > 3 || svc_ctx -> spatial_layers * svc_ctx -> temporal_layers > 4 ) ) res = VPX_CODEC_INVALID_PARAM ;
 return res ;
 }

vpx_codec_err_t vpx_svc_init ( SvcContext * svc_ctx , vpx_codec_ctx_t * codec_ctx , vpx_codec_iface_t * iface , vpx_codec_enc_cfg_t * enc_cfg ) {
 vpx_codec_err_t res ;
 int i ;
 SvcInternal * const si = get_svc_internal ( svc_ctx ) ;
 if ( svc_ctx == NULL || codec_ctx == NULL || iface == NULL || enc_cfg == NULL ) {
 return VPX_CODEC_INVALID_PARAM ;
 }
 if ( si == NULL ) return VPX_CODEC_MEM_ERROR ;
 si -> codec_ctx = codec_ctx ;
 si -> width = enc_cfg -> g_w ;
 si -> height = enc_cfg -> g_h ;
 if ( enc_cfg -> kf_max_dist < 2 ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "key frame distance too small: %d\n" , enc_cfg -> kf_max_dist ) ;
 return VPX_CODEC_INVALID_PARAM ;
 }
 si -> kf_dist = enc_cfg -> kf_max_dist ;
 if ( svc_ctx -> spatial_layers == 0 ) svc_ctx -> spatial_layers = VPX_SS_DEFAULT_LAYERS ;
 if ( svc_ctx -> spatial_layers < 1 || svc_ctx -> spatial_layers > VPX_SS_MAX_LAYERS ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "spatial layers: invalid value: %d\n" , svc_ctx -> spatial_layers ) ;
 return VPX_CODEC_INVALID_PARAM ;
 }
 res = parse_quantizer_values ( svc_ctx , si -> quantizers ) ;
 if ( res != VPX_CODEC_OK ) return res ;
 res = parse_scale_factors ( svc_ctx , si -> scale_factors ) ;
 if ( res != VPX_CODEC_OK ) return res ;
 res = parse_options ( svc_ctx , si -> options ) ;
 if ( res != VPX_CODEC_OK ) return res ;
 if ( svc_ctx -> spatial_layers < 1 ) svc_ctx -> spatial_layers = 1 ;
 if ( svc_ctx -> spatial_layers > VPX_SS_MAX_LAYERS ) svc_ctx -> spatial_layers = VPX_SS_MAX_LAYERS ;
 if ( svc_ctx -> temporal_layers < 1 ) svc_ctx -> temporal_layers = 1 ;
 if ( svc_ctx -> temporal_layers > VPX_TS_MAX_LAYERS ) svc_ctx -> temporal_layers = VPX_TS_MAX_LAYERS ;
 si -> layers = svc_ctx -> spatial_layers ;
 if ( si -> layers > 1 ) {
 float total = 0 ;
 float alloc_ratio [ VPX_SS_MAX_LAYERS ] = {
 0 }
 ;
 assert ( si -> layers <= VPX_SS_MAX_LAYERS ) ;
 for ( i = 0 ;
 i < si -> layers ;
 ++ i ) {
 int pos = i + VPX_SS_MAX_LAYERS - svc_ctx -> spatial_layers ;
 if ( pos < VPX_SS_MAX_LAYERS && si -> scaling_factor_den [ pos ] > 0 ) {
 alloc_ratio [ i ] = ( float ) ( si -> scaling_factor_num [ pos ] * 1.0 / si -> scaling_factor_den [ pos ] ) ;
 alloc_ratio [ i ] *= alloc_ratio [ i ] ;
 total += alloc_ratio [ i ] ;
 }
 }
 for ( i = 0 ;
 i < si -> layers ;
 ++ i ) {
 if ( total > 0 ) {
 enc_cfg -> ss_target_bitrate [ i ] = ( unsigned int ) ( enc_cfg -> rc_target_bitrate * alloc_ratio [ i ] / total ) ;
 }
 }
 }
 # if CONFIG_SPATIAL_SVC for ( i = 0 ;
 i < si -> layers ;
 ++ i ) enc_cfg -> ss_enable_auto_alt_ref [ i ] = si -> enable_auto_alt_ref [ i ] ;
 # endif if ( svc_ctx -> temporal_layers > 1 ) {
 int i ;
 for ( i = 0 ;
 i < svc_ctx -> temporal_layers ;
 ++ i ) {
 enc_cfg -> ts_target_bitrate [ i ] = enc_cfg -> rc_target_bitrate / svc_ctx -> temporal_layers ;
 enc_cfg -> ts_rate_decimator [ i ] = 1 << ( svc_ctx -> temporal_layers - 1 - i ) ;
 }
 }
 enc_cfg -> ss_number_layers = si -> layers ;
 enc_cfg -> ts_number_layers = svc_ctx -> temporal_layers ;
 enc_cfg -> rc_dropframe_thresh = 0 ;
 enc_cfg -> rc_resize_allowed = 0 ;
 if ( enc_cfg -> g_pass == VPX_RC_ONE_PASS ) {
 enc_cfg -> rc_min_quantizer = 33 ;
 enc_cfg -> rc_max_quantizer = 33 ;
 }
 enc_cfg -> rc_undershoot_pct = 100 ;
 enc_cfg -> rc_overshoot_pct = 15 ;
 enc_cfg -> rc_buf_initial_sz = 500 ;
 enc_cfg -> rc_buf_optimal_sz = 600 ;
 enc_cfg -> rc_buf_sz = 1000 ;
 if ( enc_cfg -> g_error_resilient == 0 && si -> use_multiple_frame_contexts == 0 ) enc_cfg -> g_error_resilient = 1 ;
 res = vpx_codec_enc_init ( codec_ctx , iface , enc_cfg , VPX_CODEC_USE_PSNR ) ;
 if ( res != VPX_CODEC_OK ) {
 svc_log ( svc_ctx , SVC_LOG_ERROR , "svc_enc_init error\n" ) ;
 return res ;
 }
 vpx_codec_control ( codec_ctx , VP9E_SET_SVC , 1 ) ;
 vpx_codec_control ( codec_ctx , VP8E_SET_TOKEN_PARTITIONS , 1 ) ;
 return VPX_CODEC_OK ;
 }

static int get_gf_active_quality ( const RATE_CONTROL * const rc , int q ) {
 return get_active_quality ( q , rc -> gfu_boost , gf_low , gf_high , arfgf_low_motion_minq , arfgf_high_motion_minq ) ;
 }

static int get_kf_active_quality ( const RATE_CONTROL * const rc , int q ) {
 return get_active_quality ( q , rc -> kf_boost , kf_low , kf_high , kf_low_motion_minq , kf_high_motion_minq ) ;
 }

int vp9_compute_qdelta_by_rate ( const RATE_CONTROL * rc , FRAME_TYPE frame_type , int qindex , double rate_target_ratio ) {
 int target_index = rc -> worst_quality ;
 int i ;
 const int base_bits_per_mb = vp9_rc_bits_per_mb ( frame_type , qindex , 1.0 ) ;
 const int target_bits_per_mb = ( int ) ( rate_target_ratio * base_bits_per_mb ) ;
 for ( i = rc -> best_quality ;
 i < rc -> worst_quality ;
 ++ i ) {
 target_index = i ;
 if ( vp9_rc_bits_per_mb ( frame_type , i , 1.0 ) <= target_bits_per_mb ) break ;
 }
 return target_index - qindex ;
 }

int vp9_compute_qdelta ( const RATE_CONTROL * rc , double qstart , double qtarget ) {
 int start_index = rc -> worst_quality ;
 int target_index = rc -> worst_quality ;
 int i ;
 for ( i = rc -> best_quality ;
 i < rc -> worst_quality ;
 ++ i ) {
 start_index = i ;
 if ( vp9_convert_qindex_to_q ( i ) >= qstart ) break ;
 }
 for ( i = rc -> best_quality ;
 i < rc -> worst_quality ;
 ++ i ) {
 target_index = i ;
 if ( vp9_convert_qindex_to_q ( i ) >= qtarget ) break ;
 }
 return target_index - start_index ;
 }

static int estimate_bits_at_q ( FRAME_TYPE frame_type , int q , int mbs , double correction_factor ) {
 const int bpm = ( int ) ( vp9_rc_bits_per_mb ( frame_type , q , correction_factor ) ) ;
 return ( ( uint64_t ) bpm * mbs ) >> BPER_MB_NORMBITS ;
 }

static int get_minq_index ( double maxq , double x3 , double x2 , double x1 ) {
 int i ;
 const double minqtarget = MIN ( ( ( x3 * maxq + x2 ) * maxq + x1 ) * maxq , maxq ) ;
 if ( minqtarget <= 2.0 ) return 0 ;
 for ( i = 0 ;
 i < QINDEX_RANGE ;
 i ++ ) if ( minqtarget <= vp9_convert_qindex_to_q ( i ) ) return i ;
 return QINDEX_RANGE - 1 ;
 }

int vp9_rc_bits_per_mb ( FRAME_TYPE frame_type , int qindex , double correction_factor ) {
 const double q = vp9_convert_qindex_to_q ( qindex ) ;
 int enumerator = frame_type == KEY_FRAME ? 3300000 : 2250000 ;
