void linux_udev_hotplug_poll ( void ) {
 struct udev_device * udev_dev ;
 usbi_mutex_static_lock ( & linux_hotplug_lock ) ;
 do {
 udev_dev = udev_monitor_receive_device ( udev_monitor ) ;
 if ( udev_dev ) {
 usbi_dbg ( "Handling hotplug event from hotplug_poll" ) ;
 udev_hotplug_event ( udev_dev ) ;
 }
 }
 while ( udev_dev ) ;
 usbi_mutex_static_unlock ( & linux_hotplug_lock ) ;
 }

static void * linux_udev_event_thread_main ( void * arg ) {
 char dummy ;
 int r ;
 struct udev_device * udev_dev ;
 struct pollfd fds [ ] = {
 {
 . fd = udev_control_pipe [ 0 ] , . events = POLLIN }
 , {
 . fd = udev_monitor_fd , . events = POLLIN }
 , }
 ;
 usbi_dbg ( "udev event thread entering." ) ;
 while ( poll ( fds , 2 , - 1 ) >= 0 ) {
 if ( fds [ 0 ] . revents & POLLIN ) {
 r = usbi_read ( udev_control_pipe [ 0 ] , & dummy , sizeof ( dummy ) ) ;
 if ( r <= 0 ) {
 usbi_warn ( NULL , "udev control pipe read failed" ) ;
 }
 break ;
 }
 if ( fds [ 1 ] . revents & POLLIN ) {
 usbi_mutex_static_lock ( & linux_hotplug_lock ) ;
 udev_dev = udev_monitor_receive_device ( udev_monitor ) ;
 if ( udev_dev ) udev_hotplug_event ( udev_dev ) ;
 usbi_mutex_static_unlock ( & linux_hotplug_lock ) ;
 }
 }
 usbi_dbg ( "udev event thread exiting" ) ;
 return NULL ;
 }

int linux_udev_stop_event_monitor ( void ) {
 char dummy = 1 ;
 int r ;
 assert ( udev_ctx != NULL ) ;
 assert ( udev_monitor != NULL ) ;
 assert ( udev_monitor_fd != - 1 ) ;
 r = usbi_write ( udev_control_pipe [ 1 ] , & dummy , sizeof ( dummy ) ) ;
 if ( r <= 0 ) {
 usbi_warn ( NULL , "udev control pipe signal failed" ) ;
 }
 pthread_join ( linux_event_thread , NULL ) ;
 udev_monitor_unref ( udev_monitor ) ;
 udev_monitor = NULL ;
 udev_monitor_fd = - 1 ;
 udev_unref ( udev_ctx ) ;
 udev_ctx = NULL ;
 close ( udev_control_pipe [ 0 ] ) ;
 close ( udev_control_pipe [ 1 ] ) ;
 udev_control_pipe [ 0 ] = - 1 ;
 udev_control_pipe [ 1 ] = - 1 ;
 return LIBUSB_SUCCESS ;
 }

static void udev_hotplug_event ( struct udev_device * udev_dev ) {
 const char * udev_action ;
 const char * sys_name = NULL ;
 uint8_t busnum = 0 , devaddr = 0 ;
 int detached ;
 int r ;
 do {
 udev_action = udev_device_get_action ( udev_dev ) ;
 if ( ! udev_action ) {
 break ;
 }
 detached = ! strncmp ( udev_action , "remove" , 6 ) ;
 r = udev_device_info ( NULL , detached , udev_dev , & busnum , & devaddr , & sys_name ) ;
 if ( LIBUSB_SUCCESS != r ) {
 break ;
 }
 usbi_dbg ( "udev hotplug event. action: %s." , udev_action ) ;
 if ( strncmp ( udev_action , "add" , 3 ) == 0 ) {
 linux_hotplug_enumerate ( busnum , devaddr , sys_name ) ;
 }
 else if ( detached ) {
 linux_device_disconnected ( busnum , devaddr , sys_name ) ;
 }
 else {
 usbi_err ( NULL , "ignoring udev action %s" , udev_action ) ;
 }
 }
 while ( 0 ) ;
 udev_device_unref ( udev_dev ) ;
 }

int linux_udev_start_event_monitor ( void ) {
 int r ;
 assert ( udev_ctx == NULL ) ;
 udev_ctx = udev_new ( ) ;
 if ( ! udev_ctx ) {
 usbi_err ( NULL , "could not create udev context" ) ;
 return LIBUSB_ERROR_OTHER ;
 }
 udev_monitor = udev_monitor_new_from_netlink ( udev_ctx , "udev" ) ;
 if ( ! udev_monitor ) {
 usbi_err ( NULL , "could not initialize udev monitor" ) ;
 goto err_free_ctx ;
 }
 r = udev_monitor_filter_add_match_subsystem_devtype ( udev_monitor , "usb" , 0 ) ;
 if ( r ) {
 usbi_err ( NULL , "could not initialize udev monitor filter for \"usb\" subsystem" ) ;
 goto err_free_monitor ;
 }
 if ( udev_monitor_enable_receiving ( udev_monitor ) ) {
 usbi_err ( NULL , "failed to enable the udev monitor" ) ;
 goto err_free_monitor ;
 }
 udev_monitor_fd = udev_monitor_get_fd ( udev_monitor ) ;
 r = fcntl ( udev_monitor_fd , F_GETFL ) ;
 if ( r == - 1 ) {
 usbi_err ( NULL , "getting udev monitor fd flags (%d)" , errno ) ;
 goto err_free_monitor ;
 }
 r = fcntl ( udev_monitor_fd , F_SETFL , r | O_NONBLOCK ) ;
 if ( r ) {
 usbi_err ( NULL , "setting udev monitor fd flags (%d)" , errno ) ;
 goto err_free_monitor ;
 }
 r = usbi_pipe ( udev_control_pipe ) ;
 if ( r ) {
 usbi_err ( NULL , "could not create udev control pipe" ) ;
 goto err_free_monitor ;
 }
 r = pthread_create ( & linux_event_thread , NULL , linux_udev_event_thread_main , NULL ) ;
 if ( r ) {
 usbi_err ( NULL , "creating hotplug event thread (%d)" , r ) ;
 goto err_close_pipe ;
 }
 return LIBUSB_SUCCESS ;
 err_close_pipe : close ( udev_control_pipe [ 0 ] ) ;
 close ( udev_control_pipe [ 1 ] ) ;
 err_free_monitor : udev_monitor_unref ( udev_monitor ) ;
 udev_monitor = NULL ;
 udev_monitor_fd = - 1 ;
 err_free_ctx : udev_unref ( udev_ctx ) ;
 udev_ctx = NULL ;
 return LIBUSB_ERROR_OTHER ;
 }

int linux_udev_scan_devices ( struct libusb_context * ctx ) {
 struct udev_enumerate * enumerator ;
 struct udev_list_entry * devices , * entry ;
 struct udev_device * udev_dev ;
 const char * sys_name ;
 int r ;
 assert ( udev_ctx != NULL ) ;
 enumerator = udev_enumerate_new ( udev_ctx ) ;
 if ( NULL == enumerator ) {
 usbi_err ( ctx , "error creating udev enumerator" ) ;
 return LIBUSB_ERROR_OTHER ;
 }
 udev_enumerate_add_match_subsystem ( enumerator , "usb" ) ;
 udev_enumerate_scan_devices ( enumerator ) ;
 devices = udev_enumerate_get_list_entry ( enumerator ) ;
 udev_list_entry_foreach ( entry , devices ) {
 const char * path = udev_list_entry_get_name ( entry ) ;
 uint8_t busnum = 0 , devaddr = 0 ;
 udev_dev = udev_device_new_from_syspath ( udev_ctx , path ) ;
 r = udev_device_info ( ctx , 0 , udev_dev , & busnum , & devaddr , & sys_name ) ;
 if ( r ) {
 udev_device_unref ( udev_dev ) ;
 continue ;
 }
 linux_enumerate_device ( ctx , busnum , devaddr , sys_name ) ;
 udev_device_unref ( udev_dev ) ;
 }
 udev_enumerate_unref ( enumerator ) ;
 return LIBUSB_SUCCESS ;
 }

static int udev_device_info ( struct libusb_context * ctx , int detached , struct udev_device * udev_dev , uint8_t * busnum , uint8_t * devaddr , const char * * sys_name ) {
 const char * dev_node ;
 dev_node = udev_device_get_devnode ( udev_dev ) ;
 if ( ! dev_node ) {
 return LIBUSB_ERROR_OTHER ;
 }
 * sys_name = udev_device_get_sysname ( udev_dev ) ;
 if ( ! * sys_name ) {
 return LIBUSB_ERROR_OTHER ;
 }
 return linux_get_device_address ( ctx , detached , busnum , devaddr , dev_node , * sys_name ) ;
 }

static int h264_frame_start ( H264Context * h ) {
 Picture * pic ;
 int i , ret ;
 const int pixel_shift = h -> pixel_shift ;
 int c [ 4 ] = {
 1 << ( h -> sps . bit_depth_luma - 1 ) , 1 << ( h -> sps . bit_depth_chroma - 1 ) , 1 << ( h -> sps . bit_depth_chroma - 1 ) , - 1 }
 ;
 if ( ! ff_thread_can_start_frame ( h -> avctx ) ) {
 av_log ( h -> avctx , AV_LOG_ERROR , "Attempt to start a frame outside SETUP state\n" ) ;
 return - 1 ;
 }
 release_unused_pictures ( h , 1 ) ;
 h -> cur_pic_ptr = NULL ;
 i = find_unused_picture ( h ) ;
 if ( i < 0 ) {
 av_log ( h -> avctx , AV_LOG_ERROR , "no frame buffer available\n" ) ;
 return i ;
 }
 pic = & h -> DPB [ i ] ;
 pic -> reference = h -> droppable ? 0 : h -> picture_structure ;
 pic -> f . coded_picture_number = h -> coded_picture_number ++ ;
 pic -> field_picture = h -> picture_structure != PICT_FRAME ;
 pic -> f . key_frame = 0 ;
 pic -> mmco_reset = 0 ;
 pic -> recovered = 0 ;
 if ( ( ret = alloc_picture ( h , pic ) ) < 0 ) return ret ;
 if ( ! h -> frame_recovered && ! h -> avctx -> hwaccel && ! ( h -> avctx -> codec -> capabilities & CODEC_CAP_HWACCEL_VDPAU ) ) avpriv_color_frame ( & pic -> f , c ) ;
 h -> cur_pic_ptr = pic ;
 unref_picture ( h , & h -> cur_pic ) ;
 if ( ( ret = ref_picture ( h , & h -> cur_pic , h -> cur_pic_ptr ) ) < 0 ) return ret ;
 if ( CONFIG_ERROR_RESILIENCE ) {
 ff_er_frame_start ( & h -> er ) ;
 h -> er . last_pic = h -> er . next_pic = NULL ;
 }
 assert ( h -> linesize && h -> uvlinesize ) ;
 for ( i = 0 ;
 i < 16 ;
 i ++ ) {
 h -> block_offset [ i ] = ( 4 * ( ( scan8 [ i ] - scan8 [ 0 ] ) & 7 ) << pixel_shift ) + 4 * h -> linesize * ( ( scan8 [ i ] - scan8 [ 0 ] ) >> 3 ) ;
 h -> block_offset [ 48 + i ] = ( 4 * ( ( scan8 [ i ] - scan8 [ 0 ] ) & 7 ) << pixel_shift ) + 8 * h -> linesize * ( ( scan8 [ i ] - scan8 [ 0 ] ) >> 3 ) ;
 }
 for ( i = 0 ;
 i < 16 ;
 i ++ ) {
 h -> block_offset [ 16 + i ] = h -> block_offset [ 32 + i ] = ( 4 * ( ( scan8 [ i ] - scan8 [ 0 ] ) & 7 ) << pixel_shift ) + 4 * h -> uvlinesize * ( ( scan8 [ i ] - scan8 [ 0 ] ) >> 3 ) ;
 h -> block_offset [ 48 + 16 + i ] = h -> block_offset [ 48 + 32 + i ] = ( 4 * ( ( scan8 [ i ] - scan8 [ 0 ] ) & 7 ) << pixel_shift ) + 8 * h -> uvlinesize * ( ( scan8 [ i ] - scan8 [ 0 ] ) >> 3 ) ;
 }
 h -> cur_pic_ptr -> reference = 0 ;
 h -> cur_pic_ptr -> field_poc [ 0 ] = h -> cur_pic_ptr -> field_poc [ 1 ] = INT_MAX ;
 h -> next_output_pic = NULL ;
 assert ( h -> cur_pic_ptr -> long_ref == 0 ) ;
 return 0 ;
 }

