static int sbr_hf_calc_npatches ( AACContext * ac , SpectralBandReplication * sbr ) {
 int i , k , last_k = - 1 , last_msb = - 1 , sb = 0 ;
 int msb = sbr -> k [ 0 ] ;
 int usb = sbr -> kx [ 1 ] ;
 int goal_sb = ( ( 1000 << 11 ) + ( sbr -> sample_rate >> 1 ) ) / sbr -> sample_rate ;
 sbr -> num_patches = 0 ;
 if ( goal_sb < sbr -> kx [ 1 ] + sbr -> m [ 1 ] ) {
 for ( k = 0 ;
 sbr -> f_master [ k ] < goal_sb ;
 k ++ ) ;
 }
 else k = sbr -> n_master ;
 do {
 int odd = 0 ;
 if ( k == last_k && msb == last_msb ) {
 av_log ( ac -> avctx , AV_LOG_ERROR , "patch construction failed\n" ) ;
 return AVERROR_INVALIDDATA ;
 }
 last_k = k ;
 last_msb = msb ;
 for ( i = k ;
 i == k || sb > ( sbr -> k [ 0 ] - 1 + msb - odd ) ;
 i -- ) {
 sb = sbr -> f_master [ i ] ;
 odd = ( sb + sbr -> k [ 0 ] ) & 1 ;
 }
 if ( sbr -> num_patches > 5 ) {
 av_log ( ac -> avctx , AV_LOG_ERROR , "Too many patches: %d\n" , sbr -> num_patches ) ;
 return - 1 ;
 }
 sbr -> patch_num_subbands [ sbr -> num_patches ] = FFMAX ( sb - usb , 0 ) ;
 sbr -> patch_start_subband [ sbr -> num_patches ] = sbr -> k [ 0 ] - odd - sbr -> patch_num_subbands [ sbr -> num_patches ] ;
 if ( sbr -> patch_num_subbands [ sbr -> num_patches ] > 0 ) {
 usb = sb ;
 msb = sb ;
 sbr -> num_patches ++ ;
 }
 else msb = sbr -> kx [ 1 ] ;
 if ( sbr -> f_master [ k ] - sb < 3 ) k = sbr -> n_master ;
 }
 while ( sb != sbr -> kx [ 1 ] + sbr -> m [ 1 ] ) ;
 if ( sbr -> num_patches > 1 && sbr -> patch_num_subbands [ sbr -> num_patches - 1 ] < 3 ) sbr -> num_patches -- ;
 return 0 ;
 }

static void sbr_env_estimate ( float ( * e_curr ) [ 48 ] , float X_high [ 64 ] [ 40 ] [ 2 ] , SpectralBandReplication * sbr , SBRData * ch_data ) {
 int e , m ;
 int kx1 = sbr -> kx [ 1 ] ;
 if ( sbr -> bs_interpol_freq ) {
 for ( e = 0 ;
 e < ch_data -> bs_num_env ;
 e ++ ) {
 const float recip_env_size = 0.5f / ( ch_data -> t_env [ e + 1 ] - ch_data -> t_env [ e ] ) ;
 int ilb = ch_data -> t_env [ e ] * 2 + ENVELOPE_ADJUSTMENT_OFFSET ;
 int iub = ch_data -> t_env [ e + 1 ] * 2 + ENVELOPE_ADJUSTMENT_OFFSET ;
 for ( m = 0 ;
 m < sbr -> m [ 1 ] ;
 m ++ ) {
 float sum = sbr -> dsp . sum_square ( X_high [ m + kx1 ] + ilb , iub - ilb ) ;
 e_curr [ e ] [ m ] = sum * recip_env_size ;
 }
 }
 }
 else {
 int k , p ;
 for ( e = 0 ;
 e < ch_data -> bs_num_env ;
 e ++ ) {
 const int env_size = 2 * ( ch_data -> t_env [ e + 1 ] - ch_data -> t_env [ e ] ) ;
 int ilb = ch_data -> t_env [ e ] * 2 + ENVELOPE_ADJUSTMENT_OFFSET ;
 int iub = ch_data -> t_env [ e + 1 ] * 2 + ENVELOPE_ADJUSTMENT_OFFSET ;
 const uint16_t * table = ch_data -> bs_freq_res [ e + 1 ] ? sbr -> f_tablehigh : sbr -> f_tablelow ;
 for ( p = 0 ;
 p < sbr -> n [ ch_data -> bs_freq_res [ e + 1 ] ] ;
 p ++ ) {
 float sum = 0.0f ;
 const int den = env_size * ( table [ p + 1 ] - table [ p ] ) ;
 for ( k = table [ p ] ;
 k < table [ p + 1 ] ;
 k ++ ) {
 sum += sbr -> dsp . sum_square ( X_high [ k ] + ilb , iub - ilb ) ;
 }
 sum /= den ;
 for ( k = table [ p ] ;
 k < table [ p + 1 ] ;
 k ++ ) {
 e_curr [ e ] [ k - kx1 ] = sum ;
 }
 }
 }
 }
 }

