 if ( sbr -> num_patches > 1 ) memcpy ( sbr -> f_tablelim + sbr -> n [ 0 ] + 1 , patch_borders + 1 , ( sbr -> num_patches - 1 ) * sizeof ( patch_borders [ 0 ] ) ) ;
