 ch_data -> t_env [ 0 ] = 0 ;
 ch_data -> t_env [ ch_data -> bs_num_env ] = abs_bord_trail ;
 abs_bord_trail = ( abs_bord_trail + ( ch_data -> bs_num_env >> 1 ) ) / ch_data -> bs_num_env ;
