 i ++ ) ch_data -> t_env [ i + 1 ] = ch_data -> t_env [ i ] + abs_bord_trail ;
 ch_data -> bs_freq_res [ 1 ] = get_bits1 ( gb ) ;
 for ( i = 1 ;
