void compute_curve_gamma_table_type_parametric ( float gamma_table [ 256 ] , float parameter [ 7 ] , int count ) {
 size_t X ;
 float interval ;
 float a , b , c , e , f ;
 float y = parameter [ 0 ] ;
 if ( count == 0 ) {
 a = 1 ;
 b = 0 ;
 c = 0 ;
 e = 0 ;
 f = 0 ;
 interval = - INFINITY ;
 }
 else if ( count == 1 ) {
 a = parameter [ 1 ] ;
 b = parameter [ 2 ] ;
 c = 0 ;
 e = 0 ;
 f = 0 ;
 interval = - 1 * parameter [ 2 ] / parameter [ 1 ] ;
 }
 else if ( count == 2 ) {
 a = parameter [ 1 ] ;
 b = parameter [ 2 ] ;
 c = 0 ;
 e = parameter [ 3 ] ;
 f = parameter [ 3 ] ;
 interval = - 1 * parameter [ 2 ] / parameter [ 1 ] ;
 }
 else if ( count == 3 ) {
 a = parameter [ 1 ] ;
 b = parameter [ 2 ] ;
 c = parameter [ 3 ] ;
 e = - c ;
 f = 0 ;
 interval = parameter [ 4 ] ;
 }
 else if ( count == 4 ) {
 a = parameter [ 1 ] ;
 b = parameter [ 2 ] ;
 c = parameter [ 3 ] ;
 e = parameter [ 5 ] - c ;
 f = parameter [ 6 ] ;
 interval = parameter [ 4 ] ;
 }
 else {
 assert ( 0 && "invalid parametric function type." ) ;
 a = 1 ;
 b = 0 ;
 c = 0 ;
 e = 0 ;
 f = 0 ;
 interval = - INFINITY ;
 }
 for ( X = 0 ;
 X < 256 ;
 X ++ ) {
 float x = X / 255.0 ;
 if ( x >= interval ) {
 gamma_table [ X ] = clamp_float ( pow ( a * x + b , y ) + c + e ) ;
 }
 else {
 gamma_table [ X ] = clamp_float ( c * x + f ) ;
 }
 }
 }

